def _allow_ios_safari_ua() -> bool:
    return (os.environ.get("KREXION_ALLOW_IOS_SAFARI_UA") or "").strip().lower() in (
        "1", "true", "yes",
    )


def _is_pure_ios_safari_ua(ua: str) -> bool:
    """True for iPhone/iPad + Version/ + Safari/ with no CriOS/Chrome/."""
    u = ua or ""
    ul = u.lower()
    if "iphone" not in ul and "ipad" not in ul:
        return False
    if "crios/" in ul or "chrome/" in ul:
        return False
    return "version/" in ul and "safari/" in ul


def _is_ios_webkit_ua(ua: str) -> bool:
    """True for iPhone/iPad + like Mac OS X with no Chrome/ or CriOS/.

    Covers pure Safari *and* WKWebView in-app shells (Mobile/15E148 +
    app marker, no Version/Safari required) that Chromium cannot
    honestly present.
    """
    ul = (ua or "").lower()
    if "iphone" not in ul and "ipad" not in ul:
        return False
    if "crios/" in ul or "chrome/" in ul:
        return False
    return "like mac os x" in ul


def _is_ios_claiming_ua(ua: str) -> bool:
    """True when UA claims iPhone/iPad (WebKit or CriOS)."""
    ul = (ua or "").lower()
    if "iphone" not in ul and "ipad" not in ul:
        return False
    return "like mac os x" in ul


def _os_from_mobile_ua(ua: str) -> str:
    """Detect android|ios|… from a (possibly coerced) UA string."""
    ul = (ua or "").lower()
    if "android" in ul and "android tv" not in ul:
        return "android"
    if ("iphone" in ul or "ipad" in ul) and "like mac os x" in ul:
        return "ios"
    if "windows nt" in ul:
        return "windows"
    if "macintosh" in ul or "mac os x" in ul:
        return "macos"
    if "linux" in ul or "x11" in ul:
        return "linux"
    return ""


def _coerce_ua_off_webkit_on_chromium(ua: str) -> str:
    """Unless KREXION_ALLOW_IOS_SAFARI_UA=1, swap iOS WebKit (Safari or
    WKWebView-without-Chrome) to Android Chrome from
    `_MOBILE_UA_POOL_ANDROID` — Chromium cannot honestly present a
    WebKit-only iOS UA."""
    if _allow_ios_safari_ua() or not _is_ios_webkit_ua(ua):
        return ua
    replacement = random.choice(_MOBILE_UA_POOL_ANDROID)
    logging.getLogger(__name__).warning(
        "Swapped iOS/WebKit UA → Android Chrome for Chromium runtime "
        "(set KREXION_ALLOW_IOS_SAFARI_UA=1 to keep iOS Safari UAs)"
    )
    return replacement


def _coerce_ios_webview_off_chromium(ua: str) -> str:
    """Alias — broader iOS WebKit coerce (Safari + WKWebView in-app)."""
    return _coerce_ua_off_webkit_on_chromium(ua)


def _normalize_mobile_ua_for_chromium(ua: str) -> Tuple[str, Dict[str, Any]]:
    """Returns (ua, meta) for Chromium-honest mobile visits.

    meta keys:
      swapped_ios: bool
      os: 'android'|'ios'|…
      is_mobile: bool
      note: str

    After WebKit coerce:
    - If UA still claims iOS but has Chromium (CriOS) — keep only when
      KREXION_ALLOW_IOS_SAFARI_UA=1; else prefer Android Chrome.
    - Detect Android vs iOS from the final UA.
    """
    original = (ua or "").strip()
    allow = _allow_ios_safari_ua()
    note = ""
    swapped_ios = False
    out = original

    coerced = _coerce_ua_off_webkit_on_chromium(out)
    if coerced != out:
        swapped_ios = True
        note = "iOS/WebKit UA → Android Chrome (Chromium honesty)"
        out = coerced

    # CriOS on iPhone/iPad: Chromium Blink ≠ iOS WebKit engine story.
    # Unless explicitly allowed, swap to Android Chrome.
    ul = (out or "").lower()
    if (
        not allow
        and ("iphone" in ul or "ipad" in ul)
        and "like mac os x" in ul
        and "crios/" in ul
    ):
        out = random.choice(_MOBILE_UA_POOL_ANDROID)
        swapped_ios = True
        note = note or "iOS CriOS UA → Android Chrome (Chromium honesty)"

    os_key = _os_from_mobile_ua(out) or "android"
    is_mobile = os_key in ("android", "ios") or any(
        t in (out or "").lower() for t in ("mobile", "iphone", "ipad", "android")
    )
    return out, {
        "swapped_ios": swapped_ios,
        "os": os_key,
        "is_mobile": bool(is_mobile),
        "note": note,
        "engine": "chromium",
    }


# ── Dual-engine (v2.7.9): iOS → Playwright WebKit, Android → Chromium ──
_WEBKIT_AVAIL: Optional[bool] = None
_WEBKIT_INSTALL_LOCK = asyncio.Lock()
_WEBKIT_INSTALL_IN_PROGRESS = False


def _ua_prefers_webkit(ua: str) -> bool:
    """iPhone/iPad family (Safari, WKWebView, CriOS) prefer WebKit engine."""
    ul = (ua or "").lower()
    return ("iphone" in ul or "ipad" in ul) and "like mac os x" in ul


def _webkit_runtime_available() -> bool:
    """True if Playwright WebKit browser is installed (cached)."""
    global _WEBKIT_AVAIL
    if _WEBKIT_AVAIL is not None:
        return bool(_WEBKIT_AVAIL)
    try:
        roots: List[Path] = []
        seen: set[str] = set()

        def _add(p: Path) -> None:
            key = str(p)
            if key in seen:
                return
            seen.add(key)
            roots.append(p)

        env_root = (os.environ.get("PLAYWRIGHT_BROWSERS_PATH") or "").strip()
        if env_root:
            _add(Path(env_root))
        _add(Path("/pw-browsers"))
        _add(Path(r"C:\Program Files\Krexion\browser-engine"))
        home = Path.home()
        _add(home / "AppData" / "Local" / "ms-playwright")
        _add(home / ".cache" / "ms-playwright")
        local = (os.environ.get("LOCALAPPDATA") or "").strip()
        if local:
            _add(Path(local) / "ms-playwright")
        for root in roots:
            try:
                if not root.is_dir():
                    continue
                for child in root.glob("webkit-*"):
                    if child.is_dir():
                        _WEBKIT_AVAIL = True
                        return True
            except Exception:
                continue
        # Best-effort: Playwright sync executable_path (no browser launch).
        try:
            from playwright.sync_api import sync_playwright as _sp

            with _sp() as _p:
                exe = getattr(getattr(_p, "webkit", None), "executable_path", None)
                if exe and Path(str(exe)).exists():
                    _WEBKIT_AVAIL = True
                    return True
        except Exception:
            pass
        _WEBKIT_AVAIL = False
        return False
    except Exception:
        _WEBKIT_AVAIL = False
        return False


async def _ensure_webkit_available() -> bool:
    """Best-effort `playwright install webkit` if missing; return availability."""
    global _WEBKIT_AVAIL, _WEBKIT_INSTALL_IN_PROGRESS
    if _webkit_runtime_available():
        return True
    browsers_root = normalize_playwright_browsers_path()
    async with _WEBKIT_INSTALL_LOCK:
        # Re-check after lock (another coroutine may have finished install).
        _WEBKIT_AVAIL = None
        if _webkit_runtime_available():
            return True
        _WEBKIT_INSTALL_IN_PROGRESS = True
        try:
            logger.warning(
                "Playwright WebKit missing — installing now (this may take ~60s)…"
            )
            try:
                import sys as _sys

                proc = await asyncio.create_subprocess_exec(
                    _sys.executable,
                    "-m",
                    "playwright",
                    "install",
                    "webkit",
                    env={**os.environ, "PLAYWRIGHT_BROWSERS_PATH": browsers_root},
                    stdout=asyncio.subprocess.PIPE,
                    stderr=asyncio.subprocess.PIPE,
                )
                try:
                    _out, err = await asyncio.wait_for(proc.communicate(), timeout=300)
                except asyncio.TimeoutError:
                    try:
                        proc.kill()
                    except Exception:
                        pass
                    logger.error("Playwright WebKit install timed out after 5 min")
                    return False
                if proc.returncode != 0:
                    logger.error(
                        "Playwright WebKit install returned %s: %s",
                        proc.returncode,
                        (err or b"").decode(errors="ignore")[:300],
                    )
                    return False
            except Exception as e:
                logger.error("Playwright WebKit install failed: %s", e)
                return False
            _WEBKIT_AVAIL = None
            ok = _webkit_runtime_available()
            if ok:
                logger.info("Playwright WebKit install: OK")
            return ok
        finally:
            _WEBKIT_INSTALL_IN_PROGRESS = False


def _normalize_mobile_ua_for_visit(ua: str) -> Tuple[str, Dict[str, Any]]:
    """Pick engine + UA for a visit: iOS→WebKit when available, else Chromium.

    If ``_ua_prefers_webkit(ua)`` and WebKit is installed:
      keep UA as-is (minor strip), meta engine=webkit, os=ios, swapped_ios=False
      note='iOS UA → Playwright WebKit engine'
    Elif prefers WebKit but WebKit NOT available:
      fall back to ``_normalize_mobile_ua_for_chromium`` (Android swap)
      meta note mentions WebKit missing → Android fallback
    Else:
      Chromium / Android path, engine=chromium
    """
    original = (ua or "").strip()
    if _ua_prefers_webkit(original) and _webkit_runtime_available():
        return original, {
            "swapped_ios": False,
            "os": "ios",
            "is_mobile": True,
            "engine": "webkit",
            "note": "iOS UA → Playwright WebKit engine",
        }
    if _ua_prefers_webkit(original) and not _webkit_runtime_available():
        out, meta = _normalize_mobile_ua_for_chromium(original)
        meta = dict(meta)
        meta["engine"] = "chromium"
        meta["note"] = (
            "WebKit not installed — iOS UA → Android Chrome (Chromium fallback)"
            if meta.get("swapped_ios")
            else (
                (meta.get("note") or "")
                + "; WebKit missing → Android Chrome fallback"
            ).strip("; ")
        )
        return out, meta
    out, meta = _normalize_mobile_ua_for_chromium(original)
    meta = dict(meta)
    meta.setdefault("engine", "chromium")
    return out, meta


def _mobile_ua_for_inapp() -> str:
    """Return a realistic MOBILE base UA for visits.

    When Playwright WebKit is installed: ~40% iOS from `_MOBILE_UA_POOL_IOS`,
    else Android. When WebKit is missing: Android Chrome only (unless
    KREXION_ALLOW_IOS_SAFARI_UA=1 → ~20% iOS). Caller must NOT rely on this
    returning the same value twice."""
    if _webkit_runtime_available():
        if random.random() < 0.40:
            return random.choice(_MOBILE_UA_POOL_IOS)
        return random.choice(_MOBILE_UA_POOL_ANDROID)
    if _allow_ios_safari_ua() and random.random() < 0.20:
        return random.choice(_MOBILE_UA_POOL_IOS)
    return random.choice(_MOBILE_UA_POOL_ANDROID)


def _apply_inapp_preset_to_uas(user_agents: List[str], want_count: int, preset_platform: str = "") -> List[str]:
    """Given the operator's UA pool + how many visits will run, return
    a MOBILE UA pool suitable for the in-app preset. Rules:
      • Empty input pool → generate `want_count` fresh mobile UAs.
      • Every MOBILE UA in input → kept as-is (already good).
      • Every DESKTOP UA in input → replaced with a mobile UA (a
        random mobile UA per slot, so the pool stays diverse).
      • 2026-07 fix C: When `preset_platform` is provided (e.g. "tiktok"),
        every mobile UA that already contains FOREIGN in-app markers of
        a DIFFERENT platform (e.g. FBAN/FBAV, Instagram, LinkedInApp,
        Snapchat) is REPLACED with a fresh mobile UA. This kills the
        "Facebook for Android" leak reported by the customer where 1
        click showed FB browser even though platform pool was 100% TikTok.
    Guarantees: returned list is never empty. `coerce_ua_for_platform`
    will then layer the FB/IG/TT in-app markers on top.
    Pure function — safe to call from job orchestrator.
    """
    try:
        from referrer_pro import _is_mobile_ua as _is_mob  # type: ignore
        from ua_profile_contract import validate_user_agent as _validate_ua
    except Exception:
        # Fallback (should never happen — referrer_pro ships alongside)
        def _is_mob(u: str) -> str:  # type: ignore
            ul = (u or "").lower()
            if ("iphone" in ul or "ipad" in ul) and "like mac os x" in ul:
                return "ios"
            if "android" in ul:
                return "android"
            return ""
        _validate_ua = None

    # 2026-07 fix C: strict in-app preset — foreign markers get scrubbed.
    # 2026-02 v2.6.18 EXPANDED: the customer's Traxun report labelled
    # visits as "WeChat for iOS", "Firefox", "Whale mobile", "Chrome",
    # even though the TikTok preset was active. Root cause: the operator
    # uploaded a mixed mobile-UA batch that contained third-party
    # browsers (WeChat, Firefox mobile, Whale, UC, Samsung Internet,
    # Opera, Edge, Line, Kakao). None of those markers were in the
    # previous foreign-list, so the UAs survived the preset gate and
    # `coerce_ua_for_platform` merely APPENDED `musical_ly_…` to a
    # WeChat/Firefox/Whale base — offer's parser detected the FIRST
    # browser signature (WeChat/Firefox/Whale) and ignored the tail.
    # New list includes ALL third-party mobile browsers whose primary
    # marker would out-rank the trailing in-app suffix in advertiser
    # UA parsers. When any of these are found in the input UA, the UA
    # is REPLACED with a fresh clean mobile base — the coerce then
    # gets a clean canvas to layer the target marker onto.
    _THIRD_PARTY_MOBILE_BROWSERS = [
        "micromessenger",   # WeChat
        "fxios", "focus",   # Firefox iOS / Firefox Focus
        "whale",            # Naver Whale mobile
        "ucbrowser", "ucweb",  # UC Browser
        "samsungbrowser",   # Samsung Internet
        "opr/", "opera",    # Opera Mobile / Opera Mini
        "edga/", "edgios/", "edgiosap", "edge/",  # Edge Mobile
        "line/", "line ",   # Line browser
        "kakaotalk",        # Kakao
        "naver ",           # Naver browser (space to avoid matching "naver.com")
        "mqqbrowser", "qqbrowser",  # QQ Browser
        "duckduckgo",       # DuckDuckGo mobile
        "brave/",           # Brave mobile
        "yandexsearch", "yabrowser",  # Yandex mobile
        "puffin",           # Puffin mobile
        "sogou",            # Sogou
        "baiduboxapp",      # Baidu app
        "miuibrowser",      # Xiaomi Mi Browser
        "huaweibrowser",    # Huawei Browser
        "vivobrowser",      # Vivo Browser
        "oppo",             # Oppo Browser (heuristic)
        "silk-accelerated", # Amazon Silk
    ]
    _pp = (preset_platform or "").strip().lower()
    if _pp == "messenger" and user_agents:
        # Messenger has no verified in-app UA contract. Preserve supplied
        # browser identities here (including desktop/custom mobile UAs);
        # coerce_ua_for_platform() will clean an app-marked/invalid value later.
        preserved = [ua for ua in user_agents if ua]
        if preserved:
            return preserved

    _FOREIGN_MARKERS: Dict[str, List[str]] = {
        "tiktok":    ["fban", "fbav", "fb_iab", "fb4a", "instagram", "linkedinapp", "snapchat", "twitter"] + _THIRD_PARTY_MOBILE_BROWSERS,
        "facebook":  ["musical_ly", "aweme", "trill_", "bytedancewebview", "instagram", "linkedinapp", "snapchat"] + _THIRD_PARTY_MOBILE_BROWSERS,
        "instagram": ["musical_ly", "aweme", "trill_", "bytedancewebview", "fban", "fb_iab", "linkedinapp", "snapchat"] + _THIRD_PARTY_MOBILE_BROWSERS,
        "snapchat":  ["musical_ly", "aweme", "trill_", "fban", "fb_iab", "instagram", "linkedinapp"] + _THIRD_PARTY_MOBILE_BROWSERS,
        "linkedin":  ["musical_ly", "aweme", "trill_", "fban", "fb_iab", "instagram", "snapchat"] + _THIRD_PARTY_MOBILE_BROWSERS,
        "twitter":   ["musical_ly", "aweme", "trill_", "fban", "fb_iab", "instagram", "linkedinapp", "snapchat"] + _THIRD_PARTY_MOBILE_BROWSERS,
        "pinterest": ["musical_ly", "aweme", "trill_", "fban", "fb_iab", "instagram", "linkedinapp", "snapchat"] + _THIRD_PARTY_MOBILE_BROWSERS,
    }
    _foreign_needles = _FOREIGN_MARKERS.get(_pp, [])

    def _has_foreign_marker(u: str) -> bool:
        if not _foreign_needles:
            return False
        ul = (u or "").lower()
        return any(n in ul for n in _foreign_needles)

    def _is_incomplete_tiktok_android(u: str) -> bool:
        """Reject native, partial, duplicated, or unsupported TikTok UAs."""
        if (_pp or "").lower() != "tiktok":
            return False
        ul = (u or "").lower()
        if "android" not in ul:
            return False
        has_tt_tail = any(
            tok in ul
            for tok in ("musical_ly", "bytedancewebview", "trill_", "tiktok/")
        )
        if not has_tt_tail:
            return False
        if _validate_ua is None:
            return "cronet/" in ul or "; wv)" not in ul
        verdict = _validate_ua(u, expected_app="tiktok")
        return not (
            verdict["valid"]
            and verdict["engine"] == "android_webview"
            and verdict["runtime_compatible"]
        )

    if not user_agents:
        n = max(1, min(int(want_count or 20), 500))
        return [_mobile_ua_for_inapp() for _ in range(n)]
    # v2.7.9 — Keep iOS/WebKit UAs when Playwright WebKit is installed;
    # scrub only when WebKit is missing (Chromium cannot present them).
    allow_ios = _allow_ios_safari_ua() or _webkit_runtime_available()
    out: List[str] = []
    for ua in user_agents:
        u = (ua or "").strip()
        if not u:
            continue
        if (
            not allow_ios
            and (_is_ios_webkit_ua(u) or (_is_ios_claiming_ua(u) and "crios/" in u.lower()))
        ):
            out.append(_mobile_ua_for_inapp())
            continue
        if _is_mob(u) and not _has_foreign_marker(u) and not _is_incomplete_tiktok_android(u):
            out.append(u)
        else:
            out.append(_mobile_ua_for_inapp())
    if not out:
        n = max(1, min(int(want_count or 20), 500))
        out = [_mobile_ua_for_inapp() for _ in range(n)]
    return out


# v1.0.12 fix: cross-platform helpers for Playwright Chromium paths.
# Pre-1.0.12 these were hardcoded to Linux conventions (chrome-linux/
# headless_shell). On native Windows installs (krexion-Setup-v1.0.x.exe
# bundles Chromium for win64) the actual binary lives at
# `chromium_headless_shell-{rev}\chrome-win\headless_shell.exe` -
# the Linux check always missed it and the backend kept reporting
# "Chromium rev XXXX not installed yet" forever, blocking every heavy
# job on Windows. The customer's backend.stderr.log showed exactly:
#   ERROR:real_user_traffic:Playwright install failed: [WinError 2]
#   The system cannot find the file specified
# These helpers return the OS-correct sub-path so the same code works
# on the cloud VPS (Linux) AND on customers' native Windows installs.
def _pw_chrome_platform_dirs() -> List[str]:
    """Platform subfolders inside chromium-* (Playwright 1.49+ uses chrome-win64)."""
    if sys.platform.startswith("win"):
        return ["chrome-win64", "chrome-win"]
    if sys.platform == "darwin":
        return ["chrome-mac"]
    return ["chrome-linux"]


def _pw_platform_dir() -> str:
    """Primary Playwright per-OS sub-folder (first match in _pw_chrome_platform_dirs)."""
    return _pw_chrome_platform_dirs()[0]


def _chromium_binary_at(base: Path, rev: str, *, headless_shell: bool = False) -> Optional[Path]:
    """Return chrome/headless_shell binary path if present under *base* for *rev*."""
    prefix = "chromium_headless_shell" if headless_shell else "chromium"
    for plat in _pw_chrome_platform_dirs():
        name = _headless_shell_binary_name() if headless_shell else _chrome_binary_name()
        bp = base / f"{prefix}-{rev}" / plat / name
        if bp.exists():
            return bp
    return None


def _headless_shell_binary_name() -> str:
    return "headless_shell.exe" if sys.platform.startswith("win") else "headless_shell"


def _chrome_binary_name() -> str:
    return "chrome.exe" if sys.platform.startswith("win") else "chrome"


# Serialize concurrent "ensure chromium installed" attempts. The preview pod's
# ephemeral filesystem can wipe the chromium binary across restarts, and the
# non-blocking startup hook in server.py may not finish before the first
# RUT job fires — so before each job launch we synchronously verify the
# browser is present, installing it with a lock if missing. This guarantees
# the very first visit NEVER fails with "Executable doesn't exist".
_CHROMIUM_INSTALL_LOCK = asyncio.Lock()
# Tracks whether an install is currently in progress so the engine-status
# API can report "installing" instead of just "missing" while the binary
# is being downloaded.
_CHROMIUM_INSTALL_IN_PROGRESS = False


# ──────────────────────────────────────────────────────────────────────
# 2026-05 — Offer-side duplicate / VPN block retry signal
# ──────────────────────────────────────────────────────────────────────
# When the offer's landing page rejects an exit-IP as "Duplicate IP" or
# "VPN/proxy detected", we want the visit slot to TRANSPARENTLY retry
# with a fresh ProxyJet IP — without recording a wasted entry in the
# report. This internal exception is raised by `process_one` and caught
# by the `worker` wrapper which loops up to `proxyjet_unique_retry_cap`
# times. The IP that triggered the block is already burned & persisted
# to `rut_burnt_ips` before the exception, so subsequent retries within
# the SAME job AND every future job will skip it at the on-demand
# probe stage.
class _OfferBlockRetryNeeded(Exception):
    """Internal signal: offer rejected this IP, retry with fresh IP without recording."""
    def __init__(self, reason: str = "", burnt_ip: str = ""):
        super().__init__(f"{reason}:{burnt_ip}")
        self.reason = reason
        self.burnt_ip = burnt_ip


def get_engine_status() -> Dict[str, Any]:
    """Return the current state of the Playwright chromium-headless-shell
    binary so the frontend can show a coloured "Engine Status" badge:
        ready      → binary present at the EXACT revision Playwright wants
        installing → install_in_progress flag is set
        missing    → binary absent and no install in progress
        error      → couldn't read browsers.json (unexpected)
    """
    browsers_root = normalize_playwright_browsers_path()
    expected: Optional[str] = None
    try:
        import json as _json
        import playwright as _pw
        bj = Path(_pw.__file__).parent / "driver" / "package" / "browsers.json"
        if bj.exists():
            with open(bj, "r") as fh:
                data = _json.load(fh)
            for entry in data.get("browsers", []):
                if entry.get("name") == "chromium-headless-shell":
                    expected = str(entry.get("revision") or "").strip() or None
                    break
    except Exception:
        expected = None

    if not expected:
        return {
            "status": "error",
            "message": "Cannot read Playwright revision metadata",
            "expected_revision": None,
            "browser_path": None,
        }

    binary_path = _chromium_binary_at(Path(browsers_root), expected or "", headless_shell=True)
    if binary_path is None and expected:
        binary_path = Path(browsers_root) / f"chromium_headless_shell-{expected}" / _pw_platform_dir() / _headless_shell_binary_name()
    # 2026-01: Detect which engine is actually being used at runtime so
    # the admin engine-status badge can show "Full Chromium (--headless=new)"
    # vs "Headless Shell (legacy)". Helps confirm the anti-detect upgrade
    # took effect on a deployed instance.
    engine_mode = "full-chromium-headless-new" if _use_full_chromium() else "chromium-headless-shell"
    full_chromium_path = _full_chromium_binary_path()
    extra = {
        "engine_mode": engine_mode,
        "full_chromium_installed": full_chromium_path is not None,
        "full_chromium_path": str(full_chromium_path) if full_chromium_path else None,
    }
    # If either binary is present we're ready. Prefer full chromium for
    # anti-detect, but the legacy headless_shell remains a valid fallback.
    if binary_path.exists() or full_chromium_path is not None:
        ready_via = "full chromium (--headless=new)" if full_chromium_path is not None else f"headless_shell rev {expected}"
        return {
            "status": "ready",
            "message": f"Chromium ready · using {ready_via}",
            "expected_revision": expected,
            "browser_path": str(full_chromium_path or binary_path),
            **extra,
        }
    if _CHROMIUM_INSTALL_IN_PROGRESS:
        return {
            "status": "installing",
            "message": f"Downloading Chromium rev {expected}…",
            "expected_revision": expected,
            "browser_path": str(binary_path),
            **extra,
        }
    return {
        "status": "missing",
        "message": f"Chromium rev {expected} not installed yet",
        "expected_revision": expected,
        "browser_path": str(binary_path),
        **extra,
    }


async def _ensure_chromium_available() -> bool:
    """Returns True when the EXACT chromium-headless-shell revision required
    by the installed Playwright Python package is present (installing it
    first if missing). Safe to call before every job — no-op when binary
    is already present.

    NOTE: Earlier versions of this helper used a glob pattern
    `chromium_headless_shell-*` which matched ANY revision present on disk
    (e.g. an old 1208 left over from a previous Playwright upgrade) and
    falsely returned True even though Playwright 1.49.x specifically wanted
    revision 1148 → BrowserType.launch() blew up with "Executable doesn't
    exist at /pw-browsers/chromium_headless_shell-1148/...". We now read
    the EXACT revision from Playwright's bundled browsers.json and verify
    that specific path exists.
    """
    browsers_root = normalize_playwright_browsers_path()

    def _expected_revision() -> Optional[str]:
        """Read the chromium-headless-shell revision Playwright expects.
        Falls back to None if the JSON layout changes."""
        try:
            import json as _json
            import playwright as _pw
            pw_root = Path(_pw.__file__).parent
            bj = pw_root / "driver" / "package" / "browsers.json"
            if not bj.exists():
                return None
            with open(bj, "r") as fh:
                data = _json.load(fh)
            for entry in data.get("browsers", []):
                if entry.get("name") == "chromium-headless-shell":
                    rev = str(entry.get("revision") or "").strip()
                    return rev or None
        except Exception as e:
            logger.debug(f"_expected_revision: {e}")
        return None

    def _binary_for(rev: Optional[str]) -> Optional[Path]:
        if not rev:
            return None
        return _chromium_binary_at(Path(browsers_root), rev, headless_shell=True)

    expected = _expected_revision()

    def _exists() -> bool:
        # Strict check: the EXACT revision Playwright wants must be present.
        if expected:
            bp = _binary_for(expected)
            if bp and bp.exists():
                return True
            return False
        # Fallback (only when we can't read browsers.json): glob check.
        try:
            root = Path(browsers_root)
            for p in root.glob("chromium_headless_shell-*"):
                rev_part = p.name.split("-", 1)[-1]
                bp = _chromium_binary_at(root, rev_part, headless_shell=True)
                if bp and bp.exists():
                    return True
        except Exception:
            pass
        return False

    if _exists():
        # ── 2026-01 Anti-detect: kick off background install of FULL
        # chromium (no-op if already present). Lets existing deploys
        # automatically upgrade to --headless=new mode on next job.
        try:
            if _full_chromium_binary_path() is None:
                asyncio.create_task(_install_full_chromium_background())
        except Exception:
            pass
        return True

    # ── 2026-01 Anti-detect: if the FULL chromium binary is already
    # installed, we don't need chromium-headless-shell at all — the
    # launcher will use full chromium with --headless=new. Treat the
    # engine as ready and skip the (sometimes-failing) shell install.
    if _full_chromium_binary_path() is not None:
        return True

    # Missing — install with a lock to prevent duplicate installs when
    # multiple jobs start in parallel on a fresh pod.
    async with _CHROMIUM_INSTALL_LOCK:
        # Re-check after acquiring lock (another coroutine may have just
        # finished the install while we waited).
        if _exists():
            return True
        global _CHROMIUM_INSTALL_IN_PROGRESS
        _CHROMIUM_INSTALL_IN_PROGRESS = True
        try:
            logger.warning(
                f"Playwright chromium-headless-shell rev {expected or '?'} missing — "
                f"installing now (this may take ~60s)…"
            )
            try:
                # v2.1.18 — Use `python -m playwright` instead of bare
                # `playwright` so the install works on Windows desktop
                # installs where the embedded Python's Scripts/ folder
                # isn't on the spawn-process PATH. `sys.executable` is
                # always the correct Python interpreter we're running
                # inside.
                import sys as _sys
                proc = await asyncio.create_subprocess_exec(
                    _sys.executable, "-m", "playwright", "install", "chromium-headless-shell",
                    env={**os.environ, "PLAYWRIGHT_BROWSERS_PATH": browsers_root},
                    stdout=asyncio.subprocess.PIPE,
                    stderr=asyncio.subprocess.PIPE,
                )
                try:
                    _out, err = await asyncio.wait_for(proc.communicate(), timeout=300)
                except asyncio.TimeoutError:
                    try: proc.kill()
                    except Exception: pass
                    logger.error("Playwright install timed out after 5 min")
                    return False
                if proc.returncode != 0:
                    logger.error(
                        f"Playwright install returned {proc.returncode}: "
                        f"{(err or b'').decode(errors='ignore')[:300]}"
                    )
                    return False
                logger.info(
                    f"Playwright chromium-headless-shell install: OK (rev {expected or '?'})"
                )
            except Exception as e:
                logger.error(f"Playwright install failed: {e}")
                return False
            # Final strict check — must satisfy the EXACT revision Playwright wants
            ok = _exists()
        finally:
            _CHROMIUM_INSTALL_IN_PROGRESS = False

    # ── 2026-01 Anti-detect: also ensure FULL chromium is installed ──
    # Fires in the background — never blocks job execution. On the first
    # run after upgrade, the next job (or two) still uses chromium-
    # headless-shell, then once full chromium finishes downloading
    # (~165MB), `_use_full_chromium()` flips to True and subsequent jobs
    # automatically launch with `--headless=new` for maximum stealth.
    try:
        if ok and _full_chromium_binary_path() is None:
            asyncio.create_task(_install_full_chromium_background())
    except Exception:
        pass
    return ok


import httpx
import pandas as pd
from user_agents import parse as ua_parse
from playwright.async_api import async_playwright, Page, BrowserContext, Browser


# ─── Full Chromium detection (2026-01: anti-detect upgrade) ────────
# When the FULL chromium binary is installed alongside the lightweight
# chromium-headless-shell, we prefer it because:
#   1. Identical code paths to headed Chrome → bypasses headless-shell
#      detection heuristics (Anura Premium, IPQS Deep, PerimeterX).
#   2. Full font set, real GPU pipeline (SwiftShader), full audio
#      subsystem — canvas / WebGL / audio fingerprints match real Chrome.
#   3. With `--headless=new` flag, runs the SAME binary as headed Chrome
#      just without a visible window. Detectors can't distinguish.
#
# Falls back to chromium-headless-shell automatically if full chromium
# isn't installed (e.g. on customer VPS that hasn't run the upgrade).
# This keeps the codebase backwards-compatible.

# Native Windows Krexion installer bundles browsers here when PLAYWRIGHT_BROWSERS_PATH
# is unset or points at a sandbox/temp dir (common in IDE test runners).
_KREXION_BROWSERS_DEFAULT = Path(r"C:\Program Files\Krexion\browser-engine")


def _browsers_search_roots() -> List[Path]:
    """Ordered list of directories that may contain chromium-* / headless_shell-*."""
    normalize_playwright_browsers_path()
    roots: List[Path] = []
    seen: set[str] = set()

    def add(p: Path) -> None:
        key = str(p)
        if key in seen:
            return
        seen.add(key)
        if p.is_dir():
            roots.append(p)

    env_root = os.environ.get("PLAYWRIGHT_BROWSERS_PATH", "").strip()
    if env_root:
        add(Path(env_root))
    exe_dir = Path(sys.executable).resolve().parent
    add(exe_dir / "browser-engine")
    add(exe_dir.parent / "browser-engine")
    add(_KREXION_BROWSERS_DEFAULT)
    add(Path("/pw-browsers"))
    return roots


def _chromium_revision_from_playwright() -> Optional[str]:
    try:
        import json as _json
        import playwright as _pw

        bj = Path(_pw.__file__).parent / "driver" / "package" / "browsers.json"
        if not bj.exists():
            return None
        with open(bj, "r") as fh:
            data = _json.load(fh)
        for entry in data.get("browsers", []):
            if entry.get("name") == "chromium":
                rev = str(entry.get("revision") or "").strip()
                return rev or None
    except Exception:
        return None
    return None


def _full_chromium_binary_path() -> Optional[Path]:
    """Return the path to the full chromium binary if installed, else None.

    Detection strategy (v2.6.49 Bug #10 fix — was falling back to
    headless-shell whenever Playwright's SDK-pinned revision in
    browsers.json diverged from what `playwright install chromium` had
    actually fetched on this host, e.g. SDK pinned rev 1148 but the CLI
    installed rev 1208, leaving chromium-1208/ on disk and no
    chromium-1148/ — the old code returned None and the RUT engine
    silently ran every job on the weaker chromium-headless-shell,
    hurting Smart Funnel stealth for every customer whose Playwright
    got upgraded):

      1. Prefer the exact revision that Playwright's SDK is pinned to
         (matches driver expectations for CDP/browser protocols). This
         is the pre-existing behaviour.
      2. If that rev is missing on disk, scan every search root for
         `chromium-*/chrome-linux/chrome` (or platform-specific binary)
         and pick the highest-numbered rev found — a stale-but-present
         full chromium beats fallback to headless-shell.
      3. Only return None when NO full chromium binary exists at all.
    """
    rev = _chromium_revision_from_playwright()
    if rev:
        for root in _browsers_search_roots():
            bp = _chromium_binary_at(root, rev, headless_shell=False)
            if bp is not None:
                return bp
    # ── v2.6.49 Bug #10 fallback: any chromium-<rev> that exists ──
    best: Optional[Tuple[int, Path]] = None
    for root in _browsers_search_roots():
        try:
            for child in root.iterdir():
                name = child.name
                if not name.startswith("chromium-"):
                    continue
                # Skip headless-shell dirs (chromium_headless_shell-*) —
                # those are matched by a different helper. We only want
                # full chromium here.
                if "headless_shell" in name or "headless-shell" in name:
                    continue
                try:
                    rev_num = int(name.split("-", 1)[1])
                except (ValueError, IndexError):
                    continue
                for plat in _pw_chrome_platform_dirs():
                    bp = child / plat / _chrome_binary_name()
                    if not bp.exists():
                        continue
                    if best is None or rev_num > best[0]:
                        best = (rev_num, bp)
                    break
        except (OSError, PermissionError):
            continue
    return best[1] if best else None


def lightweight_reporting_enabled() -> bool:
    from hardware_tune import lightweight_reporting_enabled as _fn
    return _fn()


def _report_visit_is_complete(entry: Optional[Dict[str, Any]]) -> bool:
    """True when a visit belongs in the downloadable report screenshot set.

    Complete = form/automation finished cleanly (status ok) OR conversion /
    thank-you page reached. Incomplete / failed / skipped visits keep Live
    Activity + Visual Grid behavior during the run, but their on-disk shots
    are excluded from results.zip (and purged after zip build).
    """
    if not isinstance(entry, dict):
        return False
    status = str(entry.get("status") or "").strip().lower()
    if status == "ok":
        return True
    if entry.get("conversion_page_reached") or entry.get("thank_you_reached"):
        return True
    return False


def _iter_report_shot_files(shots_dir: Path) -> List[Path]:
    """All report evidence image files under shots_dir (png/jpeg/webp)."""
    out: List[Path] = []
    try:
        root = Path(shots_dir)
    except Exception:
        return out
    if not root.is_dir():
        return out
    for pat in ("*.png", "*.jpg", "*.jpeg", "*.webp"):
        try:
            out.extend(root.glob(pat))
        except Exception:
            continue
    return out


def _shots_matching_visit_indexes(shots_dir: Path, indexes: set) -> List[Path]:
    """Return shot files whose visit_NNNNN prefix is in `indexes` (1-based)."""
    if not indexes:
        return []
    matched: List[Path] = []
    for p in _iter_report_shot_files(shots_dir):
        try:
            name = p.name
            if not name.startswith("visit_"):
                continue
            num = int(name[6:11])  # visit_00001...
            if num in indexes:
                matched.append(p)
        except Exception:
            continue
    return matched


def _purge_incomplete_report_screenshots(
    shots_dir: Path,
    report: List[Dict[str, Any]],
) -> int:
    """Delete on-disk report screenshots for visits that did not complete.

    Called after results.zip is built so Live Activity / Grid were unaffected
    during the job. Returns number of files removed.
    """
    complete_idxs = {
        int(e.get("visit_index") or 0)
        for e in (report or [])
        if _report_visit_is_complete(e) and e.get("visit_index") is not None
    }
    removed = 0
    for p in _iter_report_shot_files(shots_dir):
        try:
            name = p.name
            if not name.startswith("visit_"):
                continue
            num = int(name[6:11])
            if num in complete_idxs:
                continue
            p.unlink(missing_ok=True)
            removed += 1
        except Exception:
            continue
    return removed


def _use_full_chromium() -> bool:
    """Prefer full chromium for stealth unless operator forced light shell."""
    from hardware_tune import want_headless_shell
    if want_headless_shell():
        return False
    return _full_chromium_binary_path() is not None


async def _install_full_chromium_background() -> None:
    """Best-effort background install of the FULL chromium binary so that
    later jobs can use --headless=new mode. Logs success/failure but
    never raises — chromium-headless-shell remains the safety net."""
    if _full_chromium_binary_path() is not None:
        return
    browsers_root = normalize_playwright_browsers_path()
    try:
        logger.info("Installing full chromium binary for --headless=new mode…")
        import sys as _sys
        proc = await asyncio.create_subprocess_exec(
            _sys.executable, "-m", "playwright", "install", "chromium",
            env={**os.environ, "PLAYWRIGHT_BROWSERS_PATH": browsers_root},
            stdout=asyncio.subprocess.PIPE,
            stderr=asyncio.subprocess.PIPE,
        )
        try:
            _out, err = await asyncio.wait_for(proc.communicate(), timeout=600)
        except asyncio.TimeoutError:
            try: proc.kill()
            except Exception: pass
            logger.warning("Full chromium install timed out — staying on headless-shell")
            return
        if proc.returncode == 0:
            logger.info("Full chromium installed — --headless=new mode enabled for subsequent jobs")
        else:
            logger.warning(
                f"Full chromium install returned {proc.returncode}: "
                f"{(err or b'').decode(errors='ignore')[:200]} — staying on headless-shell"
            )
    except Exception as e:
        logger.warning(f"Full chromium install failed: {e} — staying on headless-shell")


_FULL_CHROMIUM_INSTALL_IN_PROGRESS = False


def get_headed_engine_status() -> Dict[str, Any]:
    """Engine status for headed Browser Profile launch (needs full chromium)."""
    normalize_playwright_browsers_path()
    fc = _full_chromium_binary_path()
    if fc is not None:
        return {
            "status": "ready",
            "message": f"Full Chromium ready at {fc}",
            "browser_path": str(fc),
            "engine_mode": "full-chromium-headed",
        }
    if _FULL_CHROMIUM_INSTALL_IN_PROGRESS or _CHROMIUM_INSTALL_IN_PROGRESS:
        return {
            "status": "installing",
            "message": "Downloading full Chromium for profile launch (~150 MB)…",
            "browser_path": None,
            "engine_mode": "full-chromium-headed",
        }
    return {
        "status": "missing",
        "message": "Full Chromium not installed — required for headed profile launch",
        "browser_path": None,
        "engine_mode": "full-chromium-headed",
    }


async def _ensure_full_chromium_available() -> bool:
    """Ensure full chromium binary exists for headed profile launch."""
    normalize_playwright_browsers_path()
    if _full_chromium_binary_path() is not None:
        return True
    global _FULL_CHROMIUM_INSTALL_IN_PROGRESS
    async with _CHROMIUM_INSTALL_LOCK:
        normalize_playwright_browsers_path()
        if _full_chromium_binary_path() is not None:
            return True
        _FULL_CHROMIUM_INSTALL_IN_PROGRESS = True
        browsers_root = os.environ.get("PLAYWRIGHT_BROWSERS_PATH", "/pw-browsers")
        try:
            logger.warning(
                "Full Chromium missing for profile launch — installing now (~150 MB)…"
            )
            import sys as _sys
            proc = await asyncio.create_subprocess_exec(
                _sys.executable, "-m", "playwright", "install", "chromium",
                env={**os.environ, "PLAYWRIGHT_BROWSERS_PATH": browsers_root},
                stdout=asyncio.subprocess.PIPE,
                stderr=asyncio.subprocess.PIPE,
            )
            try:
                _out, err = await asyncio.wait_for(proc.communicate(), timeout=600)
            except asyncio.TimeoutError:
                try:
                    proc.kill()
                except Exception:
                    pass
                logger.error("Full chromium install timed out after 10 min")
                return False
            if proc.returncode != 0:
                logger.error(
                    f"Full chromium install returned {proc.returncode}: "
                    f"{(err or b'').decode(errors='ignore')[:300]}"
                )
                return False
            logger.info("Full Chromium install OK — headed profile launch enabled")
            return _full_chromium_binary_path() is not None
        except Exception as e:
            logger.error(f"Full chromium install failed: {e}")
            return False
        finally:
            _FULL_CHROMIUM_INSTALL_IN_PROGRESS = False


async def _ensure_chromium_ready() -> bool:
    """Alias used by browser_bootstrap — headless shell OR full chromium."""
    if _full_chromium_binary_path() is not None:
        return True
    return await _ensure_chromium_available()


# Shared launch-args list — kept here so both the primary launch and the
# in-flight crash-recovery relaunch use the EXACT same flags. Order matters
# for some flags (e.g. --headless=new must precede --disable-features when
# they share keys), so we keep this as a single source of truth.
#
# 2026-05 — single consolidated --disable-features=... entry: Chromium
# honours ONLY the LAST --disable-features arg, so all keys MUST be in
# one comma-separated list:
#   • AutomationControlled — hide automation flag
#   • UseDnsHttpsSvcb — block HTTPS DNS records that bypass our AAAA-skip
#     and reintroduce IPv6 on Chrome 100+
#   NOTE: do NOT disable WebRtcHideLocalIpsWithMdns — that feature HIDES
#   local IPs via mDNS in real Chrome; listing it under --disable-features
#   was a leak (v2.6.30 fix).
_BROWSER_LAUNCH_ARGS_BASE = [
    "--no-sandbox",
    "--disable-dev-shm-usage",
    "--disable-features=AutomationControlled,UseDnsHttpsSvcb",
    "--disable-blink-features=AutomationControlled",
    "--force-webrtc-ip-handling-policy=disable_non_proxied_udp",
    "--disable-extensions",
    "--disable-background-networking",
    "--disable-background-timer-throttling",
    "--disable-backgrounding-occluded-windows",
    "--disable-renderer-backgrounding",
    "--disable-sync",
    "--disable-translate",
    "--disable-default-apps",
    "--disable-component-update",
    "--no-first-run",
    "--no-default-browser-check",
    "--metrics-recording-only",
    # 2026-02 Step 4 (P0 #6) — HTTP/3 / QUIC support.
    # Chrome headless mode disables QUIC by default. Real Chrome on
    # real users uses QUIC on ~25% of major sites (Google, YouTube,
    # Cloudflare CDN). Disabled-QUIC traffic is a SUBTLE cohort tell
    # picked up by Cloudflare BM v2 + Akamai BM. Re-enable.
    "--enable-quic",
    "--quic-version=h3",
    # v2.7.7 — do NOT force QUIC on every origin (removed force-all-origins
    # flag); that is unnatural vs real Chrome negotiation. Keep enable-quic + h3 only.
    # Prefer IPv4-proxy-consistent; avoid dual-stack vs IPv6-exit-reject clash.
    "--enable-features=AddressSpaceTraversal",
    # 2026-01 Anti-detect: removed `--mute-audio` — real Chrome doesn't
    # launch with audio muted by default, and detectors comparing
    # AudioContext.state can flag the discrepancy. Audio output stays
    # silent anyway because no <audio>/<video> auto-plays on lead pages.
]


async def _launch_anti_detect_browser(pw, *, variant: str = "auto") -> Browser:
    """Launch Chromium for RUT jobs with the strongest anti-detect setup
    available on this host:

      1. If the FULL chromium binary is installed → launch it with
         `--headless=new` flag. This is the SAME binary as headed Chrome,
         just without a visible window. Detectors that compare
         headless-specific signals (font rendering, audio subsystem,
         GPU pipeline) cannot distinguish it from a real user's browser.

      2. If only chromium-headless-shell is installed → launch it the
         legacy way. Fully backwards-compatible — customer VPS instances
         that haven't run the upgrade keep working exactly as before.

    ── 2026-02 v2.1.31 (Step 3) — Browser Binary Rotation ─────────────
    When `variant` is set to "brave" / "chromium" / "headless-shell" /
    "rotate", the choice is delegated to `browser_variants.pick_browser_executable`
    which returns an executable_path + extra args. "auto" (default)
    keeps the legacy `_use_full_chromium()` flow above so all existing
    jobs behave identically.

    Returns the launched Browser. Caller is responsible for closing it.
    """
    # ── 2026-02 v2.1.31 — variant override path ──
    if variant and variant.lower() != "auto":
        try:
            from browser_variants import pick_browser_executable as _pbe  # type: ignore
            pick = _pbe(variant)
            exe = pick.get("executable_path")
            args_extra = list(pick.get("args_extra") or [])
            engine = pick.get("engine_label") or variant
            if exe:
                logger.info(
                    "RUT browser variant: %s — exe=%s", engine, exe,
                )
                try:
                    v_low = (variant or "").lower()
                    # headless_shell binary is not a full Chrome — classic
                    # headless=True. Full chromium/Brave use --headless=new
                    # with headless=False so Playwright does not add legacy
                    # --headless on top.
                    use_classic_headless = (
                        v_low == "headless-shell"
                        or "headless_shell" in str(exe).lower()
                        or "headless-shell" in str(exe).lower()
                        or (engine or "").lower() == "headless-shell"
                    )
                    if use_classic_headless:
                        _allow_shell = (
                            os.environ.get("KREXION_ALLOW_HEADLESS_SHELL") or ""
                        ).strip().lower() in ("1", "true", "yes")
                        if not _allow_shell:
                            raise RuntimeError(
                                "headless-shell variant is blocked for anti-detect. "
                                "Install full Chromium (`playwright install chromium --no-shell`) "
                                "or set KREXION_ALLOW_HEADLESS_SHELL=1."
                            )
                    return await pw.chromium.launch(
                        headless=use_classic_headless,
                        executable_path=exe,
                        args=[*args_extra, *_BROWSER_LAUNCH_ARGS_BASE],
                    )
                except Exception as e:  # noqa: BLE001
                    logger.warning(
                        f"variant '{variant}' (exe={exe}) launch failed ({e}) — "
                        f"falling back to auto"
                    )
            # variant unavailable on this host → fall through to auto
        except Exception as _v_err:  # noqa: BLE001
            logger.debug(f"browser_variants import/use failed: {_v_err}")

    fc_exe = _full_chromium_binary_path() if _use_full_chromium() else None
    if fc_exe is not None:
        # Prefer the pinned full-chromium binary path over Playwright's
        # channel lookup — guarantees we launch the exact revision that
        # matches our installed build (stronger anti-detect than shell).
        try:
            browser = await pw.chromium.launch(
                executable_path=str(fc_exe),
                headless=False,
                args=["--headless=new", *_BROWSER_LAUNCH_ARGS_BASE],
            )
            logger.info(
                "RUT browser engine: full-chromium --headless=new exe=%s",
                fc_exe,
            )
            return browser
        except Exception as e:
            logger.warning(
                f"Full chromium exe launch failed ({fc_exe}, {e}) — "
                f"retrying via channel='chromium'"
            )
    if _use_full_chromium():
        # Full chromium: pass --headless=new explicitly via args. We
        # ALSO set headless=False so Playwright doesn't pass --headless
        # (legacy mode) on top of our --headless=new. The two together
        # would force old headless and defeat the whole point.
        try:
            browser = await pw.chromium.launch(
                channel="chromium",
                headless=False,
                args=["--headless=new", *_BROWSER_LAUNCH_ARGS_BASE],
            )
            logger.info("RUT browser engine: full-chromium --headless=new via channel=chromium")
            return browser
        except Exception as e:
            # Full chromium failed (missing system lib, GPU-init crash,
            # etc.) — fall back transparently to headless-shell so the
            # job still runs. Logged so operators can investigate.
            logger.warning(
                f"Full chromium launch failed ({e}) — falling back to "
                f"chromium-headless-shell (weaker stealth — run "
                f"`playwright install chromium --no-shell`)"
            )
    _allow_shell = (os.environ.get("KREXION_ALLOW_HEADLESS_SHELL") or "").strip().lower() in (
        "1", "true", "yes",
    )
    if not _allow_shell:
        raise RuntimeError(
            "Full Chromium is required for anti-detect RUT launches. "
            "Install with `playwright install chromium --no-shell`, or set "
            "KREXION_ALLOW_HEADLESS_SHELL=1 to allow weaker headless-shell fallback."
        )
    logger.warning(
        "RUT browser engine: chromium-headless-shell fallback — "
        "full chromium not found (checked roots: %s)",
        ", ".join(str(r) for r in _browsers_search_roots()),
    )
    browser = await pw.chromium.launch(
        headless=True,
        args=list(_BROWSER_LAUNCH_ARGS_BASE),
    )
    logger.info("RUT browser engine: chromium-headless-shell (legacy headless=True)")
    return browser


async def _launch_webkit_browser(pw) -> Browser:
    """Launch Playwright WebKit for iOS Safari / WKWebView visits.

    WebKit ignores most Chromium CLI flags (AutomationControlled, etc.);
    use a minimal launch. RUT jobs run headless=True — no real iPhone,
    engine fidelity only.
    """
    logger.info("RUT browser engine: Playwright WebKit (iOS traffic)")
    return await pw.webkit.launch(headless=True)


async def _launch_engine_browser(
    pw, *, engine: str = "chromium", variant: str = "auto"
) -> Browser:
    """Launch Chromium or WebKit based on ``engine``."""
    eng = (engine or "chromium").strip().lower()
    if eng == "webkit":
        return await _launch_webkit_browser(pw)
    return await _launch_anti_detect_browser(pw, variant=variant)


