logger = logging.getLogger(__name__)

RESULTS_ROOT = Path("/app/backend/real_user_traffic_results")
RESULTS_ROOT.mkdir(parents=True, exist_ok=True)

RUT_JOBS: Dict[str, Dict[str, Any]] = {}


# ──────────────────────────────────────────────────────────────────────
# 2026-06 — Live Visual Grid: Manual Takeover + Hybrid Streaming registries
# ──────────────────────────────────────────────────────────────────────
# Purpose (user ask):
#   "live visual grid mein sab smoothly live dikhe… or live visual grid mein
#    manually kam krne ka b option ho jese profile khol kr kam krte hein…
#    agr stuck ho jay to manuualy wo kaam kr liya jay"
#
# Three small in-memory registries — all STRICTLY ADDITIVE (no existing
# code path reads/writes them unless the new endpoints / new step-loop
# hook are exercised). Customer flows that never open the new UI behave
# byte-for-byte identical to before.
#
#   _LIVE_PAGES   — {"job_id:visit_idx": playwright.Page}
#       Set when a visit's browser context is ready, cleared when the
#       visit ends. Used by the input-forwarding endpoints
#       (/visits/{idx}/input/*) to drive the page directly via CDP.
#
#   _PAUSED_VISITS — {"job_id:visit_idx", ...}
#       The automation step loop checks this set BEFORE each step. If
#       the visit is paused, the loop awaits 0.5s and re-checks. Once
#       the operator resumes, the loop picks up from the next step
#       (no state is lost). Auto-cancel also lifts the pause.
#
#   _STREAM_MODE   — {"job_id:visit_idx": "off"|"grid"|"expanded"}
#       Drives the per-visit periodic screenshot daemon (`_live_streamer`).
#       "off"      → no daemon (default; preserves CPU/bandwidth)
#       "grid"     → ~700 ms cadence, jpeg quality 55 (covers idle waits)
#       "expanded" → ~150 ms cadence, jpeg quality 60 (single-tile focus)
#
# Keys are STRINGS of the form "{job_id}:{visit_idx}" to avoid the
# perennial "tuple vs (str,int)" footguns when persisting through JSON.
# ──────────────────────────────────────────────────────────────────────
_LIVE_PAGES: Dict[str, Any] = {}        # value type is playwright.async_api.Page
_PAUSED_VISITS: set[str] = set()
_STREAM_MODE: Dict[str, str] = {}        # "off" | "grid" | "expanded"
_STREAM_TASKS: Dict[str, Any] = {}       # asyncio.Task per streaming visit


def _live_key(job_id: str, visit_idx: int) -> str:
    return f"{job_id}:{int(visit_idx)}"


def register_live_page(job_id: str, visit_idx: int, page: Any) -> None:
    """Engine hook — called once a visit's Page is ready. Idempotent."""
    try:
        _LIVE_PAGES[_live_key(job_id, visit_idx)] = page
    except Exception:
        pass


def unregister_live_page(job_id: str, visit_idx: int) -> None:
    """Engine hook — called when a visit finishes (success, fail, cancel)."""
    key = _live_key(job_id, visit_idx)
    _LIVE_PAGES.pop(key, None)
    _PAUSED_VISITS.discard(key)
    _STREAM_MODE.pop(key, None)
    # Cancel any orphan stream task
    t = _STREAM_TASKS.pop(key, None)
    if t is not None:
        try:
            t.cancel()
        except Exception:
            pass


def get_live_page(job_id: str, visit_idx: int) -> Any:
    return _LIVE_PAGES.get(_live_key(job_id, visit_idx))


def is_visit_paused(job_id: str, visit_idx: int) -> bool:
    return _live_key(job_id, visit_idx) in _PAUSED_VISITS


def set_visit_paused(job_id: str, visit_idx: int, paused: bool) -> None:
    key = _live_key(job_id, visit_idx)
    if paused:
        _PAUSED_VISITS.add(key)
    else:
        _PAUSED_VISITS.discard(key)


def get_stream_mode(job_id: str, visit_idx: int) -> str:
    return _STREAM_MODE.get(_live_key(job_id, visit_idx), "off")


def _downscale_live_jpeg(
    jpeg_bytes: bytes,
    *,
    max_width: int = 800,
    quality: int = 45,
) -> bytes:
    from hardware_tune import downscale_live_jpeg
    return downscale_live_jpeg(jpeg_bytes, max_width=max_width, quality=quality)


async def _capture_live_step_jpeg(
    page: Any,
    *,
    job_id: Optional[str] = None,
    visit_idx: Optional[int] = None,
    force: bool = False,  # kept for call-site compat; always captures
) -> str:
    """Best-effort data-URL JPEG for live tiles / step progress.

    Always captures (same as pre-v2.6.65 gate). Full page + downscale so
    the preview stays light while the whole page remains visible.
    Automation path is untouched.
    """
    mode = "off"
    if job_id is not None and visit_idx is not None:
        mode = get_stream_mode(job_id, visit_idx)
    # Preview widths — readable on tiles, far fewer pixels than raw 1280+.
    if mode == "expanded":
        max_w, quality, capture_q = 960, 48, 55
    elif mode == "grid":
        max_w, quality, capture_q = 720, 42, 50
    else:
        max_w, quality, capture_q = 800, 42, 50
    try:
        import base64 as _b64
        _shot = await page.screenshot(
            type="jpeg",
            quality=capture_q,
            full_page=True,
            timeout=4000,
        )
        if len(_shot) > 1_200_000:
            _shot = await page.screenshot(
                type="jpeg", quality=capture_q, full_page=False, timeout=2500,
            )
        _shot = await asyncio.to_thread(
            _downscale_live_jpeg, _shot, max_width=max_w, quality=quality,
        )
        return "data:image/jpeg;base64," + _b64.b64encode(_shot).decode("ascii")
    except Exception:
        try:
            import base64 as _b64
            _shot = await page.screenshot(
                type="jpeg", quality=50, full_page=False, timeout=2000,
            )
            _shot = await asyncio.to_thread(
                _downscale_live_jpeg, _shot, max_width=max_w, quality=quality,
            )
            return "data:image/jpeg;base64," + _b64.b64encode(_shot).decode("ascii")
        except Exception:
            return ""


async def set_stream_mode(job_id: str, visit_idx: int, mode: str) -> None:
    """Set stream mode + spin up/down the per-visit screenshot daemon."""
    mode = (mode or "off").lower().strip()
    if mode not in ("off", "grid", "expanded"):
        mode = "off"
    key = _live_key(job_id, visit_idx)
    _STREAM_MODE[key] = mode
    # Cancel old task (the next start will pick up the new cadence)
    old = _STREAM_TASKS.pop(key, None)
    if old is not None:
        try:
            old.cancel()
        except Exception:
            pass
    if mode == "off":
        return
    page = _LIVE_PAGES.get(key)
    if page is None:
        return
    # Fire-and-forget daemon — silently exits if page closes
    _STREAM_TASKS[key] = asyncio.create_task(
        _live_streamer(job_id, visit_idx, page)
    )


async def _live_streamer(job_id: str, visit_idx: int, page: Any) -> None:
    """Per-visit screenshot daemon. Reads cadence from _STREAM_MODE so
    the operator can switch between grid (light) and expanded (smooth)
    without restarting the daemon. Exits when mode goes back to "off"
    or when the page closes.

    STRICTLY READ-ONLY against the page object — only captures
    screenshots. Does NOT interfere with the automation step loop.
    """
    key = _live_key(job_id, visit_idx)
    last_capture = 0.0
    fail_streak = 0
    try:
        while True:
            mode = _STREAM_MODE.get(key, "off")
            if mode == "off":
                return
            # Cadence by mode — full-page capture + downscale so tiles show
            # the whole page without high-res cost. Automation untouched.
            if mode == "expanded":
                interval = 0.15  # ~6-7 fps
                max_w, quality, capture_q = 960, 48, 55
            else:
                interval = 0.70  # ~1.4 fps
                max_w, quality, capture_q = 720, 42, 50
            now = time.time()
            wait = max(0.0, interval - (now - last_capture))
            if wait > 0:
                await asyncio.sleep(wait)
            last_capture = time.time()
            try:
                if getattr(page, "is_closed", lambda: False)():
                    return
                buf = await page.screenshot(
                    type="jpeg", quality=capture_q, full_page=True,
                    timeout=3500,
                )
                if len(buf) > 1_200_000:
                    buf = await page.screenshot(
                        type="jpeg", quality=capture_q, full_page=False,
                        timeout=2500,
                    )
                buf = await asyncio.to_thread(
                    _downscale_live_jpeg, buf, max_width=max_w, quality=quality,
                )
                fail_streak = 0
                import base64 as _b64
                b64 = "data:image/jpeg;base64," + _b64.b64encode(buf).decode("ascii")
                # Mirror into RUT_JOBS so the existing /live-visits poll
                # picks it up without any extra plumbing
                j = RUT_JOBS.get(job_id)
                if j is None:
                    return
                lv = j.setdefault("live_visits", {})
                v = lv.get(str(visit_idx))
                if v is None:
                    # Visit slot not yet created by the progress callback —
                    # just wait for next tick
                    continue
                v["latest_frame_b64"] = b64
                try:
                    v["page_url"] = page.url
                except Exception:
                    pass
                v["frame_source"] = mode
            except asyncio.CancelledError:
                return
            except Exception:
                fail_streak += 1
                if fail_streak >= 8:
                    return
                await asyncio.sleep(0.5)
    except Exception:
        return


# ──────────────────────────────────────────────────────────────────────
# RUT_JOBS — main per-job state registry
# ──────────────────────────────────────────────────────────────────────


# ──────────────────────────────────────────────────────────────────────
# UA → Referer auto-detection
# ──────────────────────────────────────────────────────────────────────
# When a residential visit's user-agent string identifies an in-app
# browser (TikTok, Facebook, Instagram, etc.), the destination tracker
# expects the Referer header to match the platform — otherwise the
# visit looks like a bare-browser hit and lifetime-value attribution
# breaks. This helper inspects the UA and returns the matching Referer
# URL. The engine injects it into `extra_http_headers` when creating
# the Playwright context (see `_get_referer_from_ua` call sites).
#
# Match order: most specific first (long substrings before generic).
# All match strings are case-INsensitive against the original UA.
# Returns "" for plain browser UAs — engine will either leave Referer
# unset or fall back to a Google search referer per its existing logic.
# ──────────────────────────────────────────────────────────────────────
_UA_REFERER_MAP: List[Tuple[Tuple[str, ...], str]] = [
    # In-app browsers — these strings appear in mobile webview UAs
    (("musical_ly", "musically", "tiktok", "ttwebview"), "https://www.tiktok.com/"),
    (("fban/", "fbav/", "fbios", "fb_iab", "fb4a"), "https://www.facebook.com/"),
    (("messenger", "fbms", "fb_iab/messenger"),    "https://www.messenger.com/"),
    (("instagram",),                               "https://www.instagram.com/"),
    (("snapchat",),                                "https://www.snapchat.com/"),
    (("pinterest",),                               "https://www.pinterest.com/"),
    (("reddit",),                                  "https://www.reddit.com/"),
    (("twitter", "twitterandroid", "twitterios"),  "https://twitter.com/"),
    (("linkedinapp",),                             "https://www.linkedin.com/"),
    (("whatsapp", "wa-android", "wa-ios"),         "https://www.whatsapp.com/"),
    (("telegram",),                                "https://t.me/"),
    (("youtube",),                                 "https://www.youtube.com/"),
    (("tumblr",),                                  "https://www.tumblr.com/"),
    (("kakaotalk",),                               "https://www.kakaocorp.com/"),
    (("line/",),                                   "https://line.me/"),
    (("wechat", "micromessenger"),                 "https://www.wechat.com/"),
    (("discord",),                                 "https://discord.com/"),
    (("slack",),                                   "https://slack.com/"),
    # Search-engine bots / crawlers — keep Referer empty (don't fake)
    (("googlebot", "bingbot", "yandexbot", "duckduckbot"), ""),
]


def _get_referer_from_ua(ua: str) -> str:
    """Return the matching Referer URL for an in-app-browser UA, or "" if
    the UA is a plain mobile/desktop browser.

    Examples:
        "Mozilla/5.0 ... TikTok/26.5.0 ..."     → "https://www.tiktok.com/"
        "Mozilla/5.0 ... [FBAN/FBIOS;FBAV/...]" → "https://www.facebook.com/"
        "Mozilla/5.0 ... Instagram 280..."      → "https://www.instagram.com/"
        "Mozilla/5.0 (iPhone; CPU iPhone OS...) Safari/..."  → ""  (plain Safari)
    """
    if not ua:
        return ""
    ua_lower = ua.lower()
    for needles, referer in _UA_REFERER_MAP:
        for needle in needles:
            if needle in ua_lower:
                return referer
    return ""


# ──────────────────────────────────────────────────────────────────────
# 2026-06: USER-CONFIGURABLE REFERRER OVERRIDE (per-job)
# ──────────────────────────────────────────────────────────────────────
# Default behaviour (when override is OFF) is preserved exactly:
# `_get_referer_from_ua` maps in-app browser UAs (TikTok / FB / IG / …)
# to the matching platform Referer and returns "" for plain browser UAs
# (so no Referer header is sent). Existing customers see zero change.
#
# When the operator turns the override ON in the RUT job form, the
# resolver below picks the Referer per visit according to the chosen
# strategy. Modes:
#
#   "auto"          → fall back to _get_referer_from_ua (legacy).
#   "direct"        → return "" → no Referer header at all (true
#                     direct/bookmark hit — like email-list traffic).
#   "custom"        → one fixed URL applied to EVERY visit. Use when
#                     you want every visit to look like it came from
#                     one specific ad placement / FB post / blog page.
#   "random_list"   → newline-separated pool of URLs. One picked at
#                     random per visit — useful when you have 10
#                     different FB ad creatives, IG bio links etc.
#   "google_search" → realistic organic look: a random keyword from
#                     the value pool becomes the q= param of a Google
#                     SERP URL (https://www.google.com/search?q=…).
#                     Empty pool → bare https://www.google.com/.
#   "platform_pool" → rotates through a comma-separated list of
#                     platform short-names (facebook, tiktok, instagram,
#                     youtube, twitter, snapchat, pinterest, reddit,
#                     linkedin, google, bing, …). One per visit.
#
# All modes are PURE-PYTHON and never raise — any malformed cfg
# silently falls back to legacy auto-from-UA behaviour so an operator
# typo can never break a live campaign.
# ──────────────────────────────────────────────────────────────────────
