    ("t.me",          "telegram"),
    ("telegram.me",   "telegram"),
    ("discord.com",   "discord"),
    ("discord.gg",    "discord"),
    # 2026-07 v2.6.9 CUSTOMER FIX: messenger + more search hosts
    ("messenger.com", "messenger"),
    ("m.me",          "messenger"),
    ("google.",       "google"),    # google.com, google.co.uk, google.de …
    ("bing.com",      "bing"),
    ("duckduckgo.com","duckduckgo"),
    ("yahoo.com",     "yahoo"),
    ("yandex.",       "yandex"),
