def _platform_from_referer_url(ref_url: str) -> str:
    """Infer the platform short-name from a Referer URL. Returns "" for
    unknown hosts (e.g. the user's own blog) so the engine knows NOT to
    inject platform-specific URL params on that visit.

    BUG #10 fix (2026-07): Match against the parsed hostname (exact or
    proper subdomain / TLD prefix like "google.") instead of raw
    substring so paths that CONTAIN a platform name in the URL can't
    poison the classifier. Special-case "google." and "yandex." because
    the map uses them as TLD-agnostic prefixes.
    """
    if not ref_url:
        return ""
    try:
        from urllib.parse import urlparse as _urlp
        host = (_urlp(ref_url).hostname or "").lower()
    except Exception:
        host = ""
    if not host:
        return ""
    for needle, platform in _REFERER_HOST_TO_PLATFORM:
        needle_l = needle.lower()
        # TLD-agnostic entries end with "." (e.g. "google." / "yandex.")
        # → match as a hostname prefix or interior label so ccTLDs
        # like `www.google.co.uk` classify correctly.
        if needle_l.endswith("."):
            base = needle_l[:-1]  # "google"
            if (host == base
                    or host.startswith(base + ".")
                    or ("." + base + ".") in host):
                return platform
        else:
            if host == needle_l or host.endswith("." + needle_l):
                return platform
    return ""


# ──────────────────────────────────────────────────────────────────────
# 2026-06: HMAC handshake for the tracker — must mirror the helpers in
# server.py (_kx_src_sign / build_kx_src_qs). We re-implement here so
# real_user_traffic.py stays free of circular imports back into server.
# ──────────────────────────────────────────────────────────────────────
def _rut_build_kx_src_qs(platform: str, esp: str = "", brand: str = "", traffic_type: str = "") -> str:
    """Build the `_kx_src=<p>&_kx_sig=<hmac>` query fragment that the
    engine appends to the tracker URL for each visit. Returns "" when
    `platform` is empty (no signal → tracker keeps link's static
    simulate_platform). Uses JWT_SECRET_KEY from env — same secret the
    server.py side uses to verify.

    Optional fields (2026-06):
      - `esp`   : when platform=email, names which ESP (mailchimp /
                  sendgrid / …) should drive URL-param generation so
                  the URL `mc_cid` / `_kx` etc. line up with the Referer
                  host. Signed via HMAC over `<platform>:<esp>` so
                  external attackers can't forge it.
      - `brand` : optional brand identifier (e.g. "acme") that the
                  tracker injects into utm_source / utm_campaign so a
                  customer claiming "I am Brand X's marketing" produces
                  consistent brand-tagged UTMs. Not signed — brand only
                  affects UTM text, not behaviour, so HMAC isn't needed
                  for security (worst case: someone visiting with a
                  forged `_kx_brand` gets prettier UTMs).
      - `traffic_type` : v2.6.29 — decisive paid/organic verdict for
                  this visit so the tracker can inject sub2 even when
                  it skips resolve_pro_visit for signed RUT visits.
    """
    import hmac as _hmac
    import hashlib as _hashlib
    from urllib.parse import quote
    p = (platform or "").strip().lower()
    if not p:
        return ""
    from krexion_auth_secret import get_hmac_secret
    secret = get_hmac_secret()
    key = secret.encode("utf-8") if isinstance(secret, str) else bytes(secret)
    sig = _hmac.new(key, p.encode("utf-8"), _hashlib.sha256).hexdigest()[:12]
    qs = f"_kx_src={p}&_kx_sig={sig}"
    if esp:
        esp_clean = (esp or "").strip().lower()
        if esp_clean:
            combined = f"{p}:{esp_clean}".encode("utf-8")
            esp_sig = _hmac.new(key, combined, _hashlib.sha256).hexdigest()[:12]
            qs += f"&_kx_esp={esp_clean}&_kx_esp_sig={esp_sig}"
    if brand:
        brand_clean = (brand or "").strip()[:64]
        if brand_clean:
            qs += f"&_kx_brand={quote(brand_clean, safe='')}"
    tt = (traffic_type or "").strip().lower()
    if tt in ("paid", "organic"):
        tt_sig = _hmac.new(key, tt.encode("utf-8"), _hashlib.sha256).hexdigest()[:12]
        qs += f"&_kx_traffic_type={tt}&_kx_tt_sig={tt_sig}"
    return qs


def _rut_append_kx_qs(url: str, qs_fragment: str) -> str:
    """Safely append the kx handshake to a URL (handles ? vs & correctly).
    Returns the URL unchanged when `qs_fragment` is empty."""
    if not qs_fragment or not url:
        return url
    sep = "&" if "?" in url else "?"
    return f"{url}{sep}{qs_fragment}"


# ──────────────────────────────────────────────────────────────────────
# 2026-01: ENHANCED ANTI-DETECT HELPERS
# ──────────────────────────────────────────────────────────────────────
# These helpers feed the per-visit fingerprint with extra fields that
# the stealth init-script uses to mask the headless Chrome signature
# against advanced fraud-detection tools (MaxMind minFraud, IPQuality
# Score, Anura, ArkoseLabs). All helpers are pure-Python, dependency-
# free, and never raise — failures fall back to safe defaults so the
# RUT engine's existing flow is NEVER blocked by these enhancements.
# ──────────────────────────────────────────────────────────────────────
import re as _re

_CHROME_VERSION_RE = _re.compile(r"(?:Chrome|CriOS|Edg|EdgA|EdgiOS|Chromium)/(\d+)(?:\.(\d+))?", _re.IGNORECASE)
_CHROME_FULL_VERSION_RE = _re.compile(
    r"(?:Chrome|CriOS|Edg|EdgA|EdgiOS|Chromium)/(\d+\.\d+\.\d+\.\d+)", _re.IGNORECASE
)
_SAFARI_VERSION_RE = _re.compile(r"Version/(\d+)(?:\.(\d+))?", _re.IGNORECASE)


def _extract_chrome_version(ua: str) -> Tuple[int, int]:
    """Return (major, minor) of the Chrome/Chromium version in the UA.

    Handles all Chromium-family browsers including:
      · Chrome desktop:  ".../Chrome/147.0.7727.102 ..."
      · Chrome iOS:      ".../CriOS/147.0.7727.102 ..."
      · Edge desktop:    ".../Edg/147.0.7727.102 ..."
      · Edge Android:    ".../EdgA/147.0.7727.102 ..."
      · Edge iOS:        ".../EdgiOS/147.0.7727.102 ..."
      · Chromium:        ".../Chromium/147.0.7727.102 ..."
      · Any in-app webview that embeds "Chrome/X" (Instagram, Facebook,
        TikTok Android, etc. — extracts the underlying Chrome version)

    Returns (142, 0) as a safe fallback for non-Chromium UAs (pure
    Safari / Firefox / WhatsApp Darwin) so Sec-CH-UA generation never
    crashes; callers also gate Sec-CH-UA emission on is_chromium so
    a Safari UA never gets bogus Chrome hints.
    """
    if ua:
        m = _CHROME_VERSION_RE.search(ua)
        if m:
            return int(m.group(1)), int(m.group(2) or 0)
    return 142, 0


def _extract_chrome_full_version(ua: str) -> str:
    """Return the 4-part Chrome version from UA, or a safe synthetic."""
    if ua:
        m = _CHROME_FULL_VERSION_RE.search(ua)
        if m:
            return m.group(1)
    major, minor = _extract_chrome_version(ua)
    return f"{major}.{minor or 0}.0.0"


def _ua_platform_meta(os_key: str, ua_str: str) -> Dict[str, str]:
    """Platform-version / architecture / model for userAgentData + Sec-CH-UA."""
    ua_l = (ua_str or "").lower()
    if os_key == "ios":
        m = _re.search(r"iPhone OS (\d+)_(\d+)", ua_str or "")
        pv = f"{m.group(1)}.{m.group(2)}.0" if m else "17.0.0"
        model = "iPad" if "ipad" in ua_l else "iPhone"
        return {"platform_version": pv, "architecture": "arm", "ua_model": model}
    if os_key == "android":
        m = _re.search(r"Android (\d+)(?:\.(\d+))?", ua_str or "")
        pv = f"{m.group(1)}.{m.group(2) or '0'}.0" if m else "14.0.0"
        dm = _re.search(r";\s*([^;)]+)\s+Build/", ua_str or "")
        model = (dm.group(1).strip() if dm else "SM-S928B")[:40]
        return {"platform_version": pv, "architecture": "arm", "ua_model": model}
    if os_key == "macos":
        return {"platform_version": "15.1.0", "architecture": "arm", "ua_model": ""}
    if os_key == "windows":
        arch = "arm" if "arm64" in ua_l or "aarch64" in ua_l else "x86"
        return {"platform_version": "15.0.0", "architecture": arch, "ua_model": ""}
    return {"platform_version": "6.5.0", "architecture": "x86", "ua_model": ""}


def _extract_safari_version(ua: str) -> Tuple[int, int]:
    """Return (major, minor) of the Safari version in the UA, or (17, 0)."""
    if ua:
        m = _SAFARI_VERSION_RE.search(ua)
        if m:
            return int(m.group(1)), int(m.group(2) or 0)
    return 17, 0


