def _build_client_hint_headers(fp: Dict[str, Any], ua: str) -> Dict[str, str]:
    """Return the shared contract's exact low-entropy hints in Playwright casing."""
    del fp  # The UA contract, not a separately-derived fingerprint, owns hints.
    casing = {
        "sec-ch-ua": "Sec-CH-UA",
        "sec-ch-ua-mobile": "Sec-CH-UA-Mobile",
        "sec-ch-ua-platform": "Sec-CH-UA-Platform",
    }
    return {
        casing[key]: value
        for key, value in client_hint_headers_for_ua(ua).items()
    }


def _apply_contract_client_hints(
    headers: Dict[str, str],
    ua: str,
    viewport: Optional[Dict[str, Any]] = None,
) -> Dict[str, str]:
    """Reconcile low-entropy hints; rebuild high-entropy via full_client_hints."""
    contract_hints = _build_client_hint_headers({}, ua)
    low_entropy = {"sec-ch-ua", "sec-ch-ua-mobile", "sec-ch-ua-platform"}
    high_entropy = {
        "sec-ch-ua-model",
        "sec-ch-ua-platform-version",
        "sec-ch-dpr",
        "sec-ch-ua-full-version-list",
        "sec-ch-ua-arch",
        "sec-ch-ua-bitness",
        "sec-ch-ua-wow64",
        "sec-ch-ua-full-version",
        "sec-ch-prefers-color-scheme",
        "sec-ch-prefers-reduced-motion",
        "sec-ch-viewport-width",
    }
    if contract_hints:
        drop = low_entropy | high_entropy
        result = {
            key: value for key, value in (headers or {}).items()
            if key.lower() not in drop
        }
        try:
            from anti_detect_v230 import full_client_hints as _fch
            result.update(_fch(ua, viewport) or {})
        except Exception:
            pass
        result.update(contract_hints)
        return result

    # WebKit/Gecko do not emit Chromium UA client hints. Strip both low- and
    # high-entropy Sec-CH-UA-* values if a redirected/retried request inherited
    # them from an earlier Chromium profile.
    result = {
        key: value for key, value in (headers or {}).items()
        if not key.lower().startswith("sec-ch-ua")
    }
    return result


# ──────────────────────────────────────────────────────────────────────
# 2026-01: HUMAN-LIKE BEHAVIOUR HELPERS
# ──────────────────────────────────────────────────────────────────────
# Anura / IPQS / ArkoseLabs measure mouse-movement entropy, scroll-
# velocity variance, and dwell time. A bot that jumps cursor straight
# to a button + fills a form in 800ms = instant fraud flag even if every
# JS API is masked. These helpers add realistic warm-up behaviour at
# the right moments without touching the existing form_filler flow.
# ──────────────────────────────────────────────────────────────────────
async def _human_warmup(page: Any, fp: Dict[str, Any], *, paranoia: bool = False) -> None:
    """Simulate a real user landing on a page: read pause + mouse jitter
    + a few realistic scrolls. NEVER raises — every failure is swallowed
    so an unrelated runtime quirk in the page can't abort the visit."""
    try:
        viewport = fp.get("viewport") or {"width": 1280, "height": 800}
        vw = max(320, int(viewport.get("width", 1280)))
        vh = max(480, int(viewport.get("height", 800)))

        # Initial read pause — real users don't move for ~0.8-2.5s on land
        # Step 5 (Big-2): paranoia mode doubles dwells + adds extra moves
        if paranoia:
            await asyncio.sleep(random.uniform(2.5, 5.5))
        else:
            await asyncio.sleep(random.uniform(0.8, 2.5))

        # Mouse jitter — 3-6 small bezier-style moves (paranoia: 8-14)
        if not fp.get("is_mobile"):
            try:
                x, y = random.randint(50, vw - 50), random.randint(50, vh - 50)
                await page.mouse.move(x, y, steps=random.randint(8, 20))
                await asyncio.sleep(random.uniform(0.15, 0.45))
                _move_count = random.randint(8, 14) if paranoia else random.randint(3, 6)
                for _ in range(_move_count):
                    x = max(10, min(vw - 10, x + random.randint(-180, 180)))
                    y = max(10, min(vh - 10, y + random.randint(-120, 120)))
                    await page.mouse.move(x, y, steps=random.randint(6, 14))
                    _dwell_max = 0.65 if paranoia else 0.32
                    await asyncio.sleep(random.uniform(0.08, _dwell_max))
            except Exception:
                pass

        # Scroll down 1-3 times then occasional scroll back up (paranoia: 3-6)
        try:
            _scrolls = random.randint(3, 6) if paranoia else random.randint(1, 3)
            for _ in range(_scrolls):
                await page.mouse.wheel(0, random.randint(180, 620))
                await asyncio.sleep(random.uniform(0.35, 1.4))
            if random.random() < (0.7 if paranoia else 0.4):
                await page.mouse.wheel(0, -random.randint(80, 240))
                await asyncio.sleep(random.uniform(0.25, 0.8))
        except Exception:
            pass

        # Final settle pause (paranoia: 1.5-3.5s, normal: 0.3-1.1s)
        if paranoia:
            await asyncio.sleep(random.uniform(1.5, 3.5))
        else:
            await asyncio.sleep(random.uniform(0.3, 1.1))
    except Exception:
        pass


async def _human_pre_submit_dwell(page: Any, fp: Dict[str, Any]) -> None:
    """Pause + small jitter right before submit so the form-fill-to-submit
    interval matches a real human's review cadence (3-9s)."""
    try:
        await asyncio.sleep(random.uniform(2.2, 6.5))
        if not fp.get("is_mobile"):
            try:
                viewport = fp.get("viewport") or {"width": 1280, "height": 800}
                vw = max(320, int(viewport.get("width", 1280)))
                vh = max(480, int(viewport.get("height", 800)))
                x = random.randint(50, vw - 50)
                y = random.randint(50, vh - 50)
                await page.mouse.move(x, y, steps=random.randint(6, 16))
            except Exception:
                pass
        await asyncio.sleep(random.uniform(0.4, 1.5))
    except Exception:
        pass


# ──────────────────────────────────────────────────────────────────────
# 2026-01 Phase 4 — Lead-validation interactions + Mobile CTIT delay
# ──────────────────────────────────────────────────────────────────────
# These additive helpers patch the last two gaps in the anti-detect
# stack against affiliate-network fraud layers (MaxBounty / Perform[cb]
# / Glitchy / TrustedForm / Jornaya / AppsFlyer Protect360):
#
# 4a. `_emit_lead_validation_interactions` — TrustedForm and Jornaya
#     LeadiD both score a session on the number and type of DOM events
#     they witness during form completion. Pure `page.fill()` from
#     Playwright sets the input value DIRECTLY without firing the
#     mousedown/mouseup/focus/blur/keydown/keyup chain a real human
#     would generate. This helper walks every visible form field, fires
#     the realistic event chain, and dispatches an `input` event so
#     ActiveProspect's & Jornaya's collector scripts log meaningful
#     telemetry — turning a previously "bot-like" session into a
#     "human" one. NEVER fills any data — only fires events on already-
#     populated fields.
#
# 4b. `_apply_mobile_ctit_delay` — AppsFlyer Protect360 and Adjust's
#     fraud rules flag any mobile install whose Click-To-Install-Time
#     (CTIT) is <10 seconds OR shows an abnormally narrow distribution.
#     Real users on mobile take 30-300s to click → view store → install
#     → first-launch. This helper inserts a per-visit random sleep
#     drawn from a realistic CTIT distribution BEFORE the form submit
#     fires, but only for mobile UAs and only when env var
#     `RUT_MOBILE_CTIT_DELAY=true`. Default OFF so existing customer
#     flows are byte-identical until they opt in.
# ──────────────────────────────────────────────────────────────────────
async def _emit_lead_validation_interactions(page: Any, fp: Dict[str, Any]) -> None:
    """Fire realistic DOM events on every visible form field so
    TrustedForm / Jornaya / ActiveProspect collectors record genuine
    interaction telemetry. NEVER changes field values — only emits
    focus / blur / input / keydown / keyup / mousedown / mouseup
    events. Safe-failed at every layer; an exception in any single
    field never blocks the visit."""
    try:
        # Build a list of visible, interactive form fields. Skipping
        # hidden / disabled inputs because TrustedForm itself skips
        # them — firing events on a hidden input would look unnatural.
        fields = await page.evaluate(r"""() => {
            const out = [];
            const sel = 'input, select, textarea';
            const els = document.querySelectorAll(sel);
            for (let i = 0; i < els.length && i < 30; i++) {
                const el = els[i];
                if (!el) continue;
                const t = (el.type || '').toLowerCase();
                if (t === 'hidden' || t === 'submit' || t === 'button' || t === 'image') continue;
                if (el.disabled || el.readOnly) continue;
                const r = el.getBoundingClientRect();
                if (!r || r.width === 0 || r.height === 0) continue;
                const cs = window.getComputedStyle(el);
                if (cs.visibility === 'hidden' || cs.display === 'none') continue;
                if (r.top < 0 || r.top > window.innerHeight + 200) continue;
                out.push({
                    cx: Math.max(2, Math.min(window.innerWidth - 2, r.left + r.width / 2)),
                    cy: Math.max(2, Math.min(window.innerHeight - 2, r.top + r.height / 2)),
                    tag: el.tagName.toLowerCase(),
                    type: t,
                    has_value: !!(el.value && String(el.value).length > 0),
                });
            }
            return out;
        }""")
    except Exception:
        return
    if not fields:
        return

    for idx, fld in enumerate(fields):
        try:
            cx, cy = int(fld.get("cx", 100)), int(fld.get("cy", 100))
            has_value = bool(fld.get("has_value"))
            # Brief mouse approach with a few steps so MouseEvent.movementX
            # values look natural (real users don't teleport the cursor).
            try:
                await page.mouse.move(cx, cy, steps=random.randint(4, 9))
                await asyncio.sleep(random.uniform(0.05, 0.18))
                await page.mouse.down()
                await asyncio.sleep(random.uniform(0.02, 0.08))
                await page.mouse.up()
            except Exception:
                pass
            await asyncio.sleep(random.uniform(0.08, 0.25))
            # Dispatch synthetic events: focus → keydown → keyup → input
            # → change → blur. The collector scripts hook these
            # specific event types; firing them on already-populated
            # fields produces "user typed here" telemetry without
            # touching the value Playwright already set.
            try:
                await page.evaluate(r"""({i, hasValue}) => {
                    const all = document.querySelectorAll('input, select, textarea');
                    let visIdx = 0;
                    for (let k = 0; k < all.length; k++) {
                        const el = all[k];
                        const t = (el.type || '').toLowerCase();
                        if (t === 'hidden' || t === 'submit' || t === 'button' || t === 'image') continue;
                        if (el.disabled || el.readOnly) continue;
                        const r = el.getBoundingClientRect();
                        if (!r || r.width === 0 || r.height === 0) continue;
                        const cs = window.getComputedStyle(el);
                        if (cs.visibility === 'hidden' || cs.display === 'none') continue;
                        if (visIdx === i) {
                            const fire = (type, init) => {
                                try {
                                    let ev;
                                    if (type === 'keydown' || type === 'keyup' || type === 'keypress') {
                                        ev = new KeyboardEvent(type, Object.assign({ bubbles: true, cancelable: true, key: 'a', code: 'KeyA', keyCode: 65, which: 65 }, init || {}));
                                    } else if (type === 'mousedown' || type === 'mouseup' || type === 'mousemove' || type === 'click') {
                                        ev = new MouseEvent(type, Object.assign({ bubbles: true, cancelable: true }, init || {}));
                                    } else if (type === 'input') {
                                        ev = new InputEvent(type, Object.assign({ bubbles: true, cancelable: false, data: 'a', inputType: 'insertText' }, init || {}));
                                    } else {
                                        ev = new Event(type, { bubbles: true, cancelable: true });
                                    }
                                    el.dispatchEvent(ev);
                                } catch (e) {}
                            };
                            try { el.focus(); } catch (e) {}
                            fire('focus');
                            fire('focusin');
                            if (hasValue) {
                                // Each "typed character" — 3-6 keystrokes per
                                // field — fires keydown / keyup / input.
                                const n = 3 + Math.floor(Math.random() * 4);
                                for (let s = 0; s < n; s++) {
                                    fire('keydown');
                                    fire('keypress');
                                    fire('input');
                                    fire('keyup');
                                }
                            }
                            fire('change');
                            fire('blur');
                            fire('focusout');
                            return true;
                        }
                        visIdx++;
                    }
                    return false;
                }""", {"i": idx, "hasValue": has_value})
            except Exception:
                pass
            # Small idle gap between fields (real users pause)
            await asyncio.sleep(random.uniform(0.18, 0.55))
        except Exception:
            continue

    # Final scroll — Jornaya specifically logs scroll events as a
    # session-quality signal.
    try:
        await page.mouse.wheel(0, random.randint(60, 180))
        await asyncio.sleep(random.uniform(0.15, 0.4))
    except Exception:
        pass


async def _apply_mobile_ctit_delay(fp: Dict[str, Any]) -> int:
    """Apply a per-visit random delay sourced from a realistic mobile
    Click-To-Install-Time distribution. Returns the number of seconds
    actually slept (0 if the delay was skipped).

    Activation rules (all must be true):
      • The visit's fingerprint marks the device as mobile.
      • Env var ``RUT_MOBILE_CTIT_DELAY`` is truthy ("1"/"true"/"yes").

    Bounds are env-tunable (defaults match the real-user 25th-75th
    percentile reported by AppsFlyer's 2025 CTIT studies):
      • RUT_MOBILE_CTIT_MIN_SEC = 25 (default)
      • RUT_MOBILE_CTIT_MAX_SEC = 180 (default)

    NEVER raises — any config-parsing issue → 0s sleep.
    """
    try:
        if not fp.get("is_mobile"):
            return 0
        flag = os.environ.get("RUT_MOBILE_CTIT_DELAY", "").strip().lower()
        if flag not in ("1", "true", "yes", "on"):
            return 0
        try:
            mn = max(0, int(os.environ.get("RUT_MOBILE_CTIT_MIN_SEC", "25")))
        except (TypeError, ValueError):
            mn = 25
        try:
            mx = max(mn + 1, int(os.environ.get("RUT_MOBILE_CTIT_MAX_SEC", "180")))
        except (TypeError, ValueError):
            mx = max(mn + 1, 180)
        # Triangular distribution centred near the 40s mode — matches
        # the AppsFlyer "Real Mobile Install" curve more accurately
        # than a flat uniform random (which clusters CTIT visibly).
        mid = min(mx - 1, max(mn + 1, int(mn + (mx - mn) * 0.35)))
        secs = int(random.triangular(mn, mx, mid))
        # Hard cap so a runaway env-misconfig can't park a worker for
        # an hour by accident — 600s max regardless of env.
        secs = max(0, min(600, secs))
        if secs <= 0:
            return 0
        await asyncio.sleep(secs)
        return secs
    except Exception:
        return 0


def _device_name_from_ua(ua_str: str) -> str:
    """Extract a human-readable device name from a user-agent string.

    Strategy:
      1. Let the `user_agents` library try first (handles most Android device
         codes like "SM-S918U" → "Samsung SM-S918U" and "Pixel 8 Pro").
      2. For iOS UAs (which never contain the exact model), fall back to a
         regex over CPU / hardware hints, else return "iPhone" / "iPad".
      3. Windows/macOS/Linux: return OS name + short hardware hint.
    """
    import re
    s = ua_str or ""
    try:
        ua = ua_parse(s)
    except Exception:
        ua = None

    # 1. Library-parsed brand + model (works great for Android)
    if ua and ua.device:
        brand = (ua.device.brand or "").strip()
        model = (ua.device.model or "").strip()
        family = (ua.device.family or "").strip()
        if brand and model and brand.lower() not in model.lower():
            return f"{brand} {model}".strip()
        if model and model.lower() not in ("generic", "smartphone", "other"):
            return model
        if family and family.lower() not in ("generic", "smartphone", "other"):
            return family

    sl = s.lower()

    # 2. iOS — pull iPhone/iPad + model hint if we can, otherwise fall back
    if "iphone" in sl or ("cpu iphone os" in sl):
        # Try to find an explicit model (rare but possible): "iPhone 15 Pro"
        m = re.search(r"iPhone\s*(?:OS\s*)?(\d{1,2}(?:[._]\d{1,2})?)?\s*(?:Max|Pro|Plus|mini)?",
                      s, flags=re.I)
        # Prefer an iOS version tag ("iOS 17.1") to differentiate
        iosv = ""
        m2 = re.search(r"iphone os (\d+[._]\d+)", sl)
        if m2:
            iosv = m2.group(1).replace("_", ".")
        return f"iPhone (iOS {iosv})" if iosv else "iPhone"
    if "ipad" in sl:
        return "iPad"

    # 3. Android fallback when the library couldn't detect a model
    if "android" in sl:
        # Pull the "build" code inside parentheses, e.g. "(Linux; Android 14; SM-S918U)"
        m = re.search(r"android\s+[\d.]+;\s*([^;)\s][^;)]*?)(?:\)|;|\s+build)", s, flags=re.I)
        if m:
            model = m.group(1).strip()
            if model and not model.lower().startswith("linux"):
                return f"Android — {model}"
        return "Android"

    # 4. Desktop
    if "windows" in sl:
        m = re.search(r"windows nt (\d+\.\d+)", sl)
        return f"Windows {m.group(1)}" if m else "Windows PC"
    if "macintosh" in sl or "mac os x" in sl:
        return "Mac"
    if "linux" in sl:
        return "Linux"
    return "Unknown"


# ─── UA → device fingerprint ─────────────────────────────────────
def _os_key_from_ua(ua_str: str) -> str:
    """Return a lowercase OS key matching the frontend's allowed_os chips."""
    try:
        ua = ua_parse(ua_str or "")
        fam = (ua.os.family or "").lower()
    except Exception:
        fam = ""
    if "android" in fam:
        return "android"
    if "ios" in fam or "iphone" in fam or "ipad" in fam:
        return "ios"
    if "windows" in fam:
        return "windows"
    if "mac" in fam:
        return "macos"
    if any(k in fam for k in ("linux", "ubuntu", "fedora", "debian", "chromium os", "chrome os")):
        return "linux"
    return "other"


def _pick_android_gpu_from_ua(ua_str: str) -> Tuple[str, str, int, int]:
    """2026-06-14: Couple Android WebGL renderer + device-memory + hardware-
    concurrency to the UA's device model. Earlier code picked a RANDOM
    Adreno/Mali per visit regardless of device → FingerprintJS Pro v4
    catches "UA says Pixel 7 (Tensor G2 → Mali-G710) but WebGL says
    Adreno 740" instantly.

    Returns (webgl_vendor, webgl_renderer, hardware_concurrency, device_memory).
    """
    ua = (ua_str or "").lower()
    # Google Pixel — Tensor SoCs use ARM Mali GPUs
    if "pixel 8" in ua or "pixel 9" in ua or "pixel 10" in ua:
        return ("Google Inc. (ARM)",
                "ANGLE (ARM, Mali-G715 MC7, OpenGL ES 3.2)",
                random.choice([8, 9]),
                random.choice([8, 12]))
    if "pixel 7" in ua or "pixel 6" in ua:
        return ("Google Inc. (ARM)",
                "ANGLE (ARM, Mali-G710 MP7, OpenGL ES 3.2)",
                random.choice([8, 9]),
                random.choice([6, 8, 12]))
    if "pixel" in ua:
        return ("Google Inc. (ARM)",
                "ANGLE (ARM, Mali-G78 MP24, OpenGL ES 3.2)",
                random.choice([6, 8]),
                random.choice([4, 6, 8]))
    # Samsung Galaxy S24 Ultra (SM-S928), S23 Ultra (SM-S918) — Snapdragon
    # 8 Gen 2/3 → Adreno 740/750 GPU + 8-12 GB RAM
    if "sm-s928" in ua or "sm-s938" in ua:
        return ("Google Inc. (Qualcomm)",
                "ANGLE (Qualcomm, Adreno (TM) 750, OpenGL ES 3.2)",
                8, 12)
    if "sm-s918" in ua or "sm-s928b" in ua:
        return ("Google Inc. (Qualcomm)",
                "ANGLE (Qualcomm, Adreno (TM) 740, OpenGL ES 3.2)",
                8, random.choice([8, 12]))
    # Samsung Galaxy S21 (SM-G991) — Exynos 2100 → Mali-G78 (intl) or
    # Adreno 660 (US). We can't tell from UA which region, default to
    # the more globally common Mali variant.
    if "sm-g991" in ua:
        return ("Google Inc. (ARM)",
                "ANGLE (ARM, Mali-G78 MP14, OpenGL ES 3.2)",
                8, 8)
    # Samsung A-series — mid-range, MediaTek + Mali
    if "sm-a546" in ua:
        return ("Google Inc. (ARM)",
                "ANGLE (ARM, Mali-G68 MP5, OpenGL ES 3.2)",
                8, random.choice([6, 8]))
    # OnePlus / Xiaomi / Realme — Snapdragon mostly → Adreno
    if any(x in ua for x in ("cph24", "cph23", "23049", "2311drk", "rmx38", "rmx37")):
        return ("Google Inc. (Qualcomm)",
                random.choice([
                    "ANGLE (Qualcomm, Adreno (TM) 740, OpenGL ES 3.2)",
                    "ANGLE (Qualcomm, Adreno (TM) 730, OpenGL ES 3.2)",
                    "ANGLE (Qualcomm, Adreno (TM) 660, OpenGL ES 3.2)",
                ]),
                8, random.choice([8, 12]))
    # Motorola moto g — usually MediaTek Dimensity → Mali
    if "moto g" in ua:
        return ("Google Inc. (ARM)",
                "ANGLE (ARM, Mali-G57 MC2, OpenGL ES 3.2)",
                random.choice([6, 8]),
                random.choice([4, 6, 8]))
    # Vivo / Oppo — mix; default to Adreno (most popular SoC pairing)
    if any(x in ua for x in ("v2312", "cph2423")):
        return ("Google Inc. (ARM)",
                "ANGLE (ARM, Mali-G77 MC9, OpenGL ES 3.2)",
                8, 8)
    # Generic Android fallback — random plausible
    return ("Google Inc. (Qualcomm)",
            random.choice([
                "ANGLE (Qualcomm, Adreno (TM) 740, OpenGL ES 3.2)",
                "ANGLE (Qualcomm, Adreno (TM) 730, OpenGL ES 3.2)",
                "ANGLE (ARM, Mali-G78 MP24, OpenGL ES 3.2)",
                "ANGLE (Qualcomm, Adreno (TM) 660, OpenGL ES 3.2)",
            ]),
            random.choice([6, 8]),
            random.choice([4, 6, 8]))


def _pick_ios_gpu_from_ua(ua_str: str) -> Tuple[str, str, int, int]:
    """iOS device → Apple GPU + memory mapping. iPhone 15/16 Pro = A17/A18
    Pro → 8GB; standard iPhone 15/16 = A16/A17 → 6/8GB; iPhone 13/14 = A15
    → 4/6GB; iPhone 11/12 = A13/A14 → 4GB.
    """
    ua = (ua_str or "").lower()
    if "iphone17" in ua:  # iPhone 16 series
        return ("Apple Inc.", "Apple A18 GPU",
                6, random.choice([8, 12]))
    if "iphone16" in ua:  # iPhone 15 Pro series
        return ("Apple Inc.", "Apple A17 Pro GPU",
                6, 8)
    if "iphone15" in ua:  # iPhone 14 Pro / 15 standard
        return ("Apple Inc.", "Apple A16 GPU",
                6, 8)
    if "iphone14" in ua:  # iPhone 13 / 14
        return ("Apple Inc.", "Apple A15 GPU",
                6, random.choice([4, 6]))
    if "iphone13" in ua:  # iPhone 12 series
        return ("Apple Inc.", "Apple A14 GPU",
                6, 4)
    if "iphone12" in ua:  # iPhone 11 series
        return ("Apple Inc.", "Apple A13 GPU",
                6, 4)
    return ("Apple Inc.", "Apple GPU",
            random.choice([4, 6]),
            random.choice([4, 6, 8]))


def _sanitize_swiftshader_webgl(
    os_key: str,
    webgl_vendor: str,
    webgl_renderer: str,
) -> Tuple[str, str]:
    """Replace SwiftShader / llvmpipe software-render signatures with a
    realistic GPU string for the target OS. Headless-shell sometimes
    reports software GL even when our init script claims a real GPU."""
    bad = ("swiftshader", "llvmpipe", "softpipe", "lavapipe", "microsoft basic render")
    if not any(b in (webgl_renderer or "").lower() for b in bad):
        return webgl_vendor, webgl_renderer
    if os_key == "windows":
        return "Google Inc. (NVIDIA)", random.choice([
            "ANGLE (NVIDIA, NVIDIA GeForce GTX 1650 Direct3D11 vs_5_0 ps_5_0)",
            "ANGLE (NVIDIA, NVIDIA GeForce RTX 3060 Direct3D11 vs_5_0 ps_5_0)",
            "ANGLE (Intel, Intel(R) UHD Graphics 630 Direct3D11 vs_5_0 ps_5_0)",
        ])
    if os_key == "macos":
        return "Google Inc. (Apple)", random.choice([
            "ANGLE (Apple, Apple M1 Pro, OpenGL 4.1)",
            "ANGLE (Apple, Apple M2, OpenGL 4.1)",
            "ANGLE (Apple, Apple M3, OpenGL 4.1)",
        ])
    if os_key == "linux":
        return "Google Inc. (Intel)", "ANGLE (Intel, Mesa Intel(R) UHD Graphics 620)"
    if os_key in ("android", "ios"):
        return "Google Inc. (Qualcomm)", random.choice([
            "ANGLE (Qualcomm, Adreno (TM) 740, OpenGL ES 3.2)",
            "ANGLE (Qualcomm, Adreno (TM) 730, OpenGL ES 3.2)",
            "ANGLE (ARM, Mali-G78 MP24, OpenGL ES 3.2)",
        ])
    return webgl_vendor, webgl_renderer


def _auto_identity_label(job_id: str) -> str:
    """Stable per-job identity label when the operator leaves the field blank."""
    slug = (job_id or "").replace("-", "").strip()[:12]
    return f"rut-{slug}" if slug else "rut-auto"


def _fingerprint_from_ua(ua_str: str) -> Dict[str, Any]:
    """Derive viewport / DPR / platform / mobile flags from a user-agent."""
    try:
        ua = ua_parse(ua_str or "")
    except Exception:
        ua = None

    os_key = _os_key_from_ua(ua_str)
    is_mobile = bool(ua and ua.is_mobile)
    is_tablet = bool(ua and ua.is_tablet)

    # Generated mobile UAs encode immutable hardware claims. Keep the screen
    # and DPR deterministic; randomization is reserved for compatible desktop
    # profiles where the UA does not identify a physical device.
    if os_key == "ios":
        platform = "iPhone" if not is_tablet else "iPad"
        vendor = "Apple Computer, Inc."
        ios_profiles = {
            "iphone12,1": (414, 896, 2.0),
            "iphone12,3": (375, 812, 3.0),
            "iphone13,2": (390, 844, 3.0),
            "iphone14,5": (390, 844, 3.0),
            "iphone15,2": (393, 852, 3.0),
            "iphone15,3": (430, 932, 3.0),
            "iphone16,1": (393, 852, 3.0),
            "iphone17,2": (440, 956, 3.0),
            "ipad13,1": (820, 1180, 2.0),
            "ipad14,3": (834, 1194, 2.0),
            "ipad14,5": (1024, 1366, 2.0),
        }
        model_match = re.search(r"\b(iPhone\d+,\d+|iPad\d+,\d+)\b", ua_str or "", re.I)
        model_key = model_match.group(1).lower() if model_match else ""
        width, height, dpr = ios_profiles.get(
            model_key,
            (820, 1180, 2.0) if is_tablet or "ipad" in (ua_str or "").lower()
            else (390, 844, 3.0),
        )
        viewport = {"width": width, "height": height}
        # 2026-06-14: device-coupled GPU + memory (was random — caused
        # WebGL renderer ≠ UA device mismatch flagged by FingerprintJS).
        webgl_vendor, webgl_renderer, hc, dm = _pick_ios_gpu_from_ua(ua_str)
    elif os_key == "android":
        platform = "Linux armv8l"
        vendor = "Google Inc."
        android_profiles = {
            "moto g 5g - 2024": (360, 806, 2.0),
            "sm-s918b": (412, 892, 2.625),
            "sm-s928b": (456, 989, 3.157),
            "sm-a546b": (412, 892, 2.625),
            "sm-g991b": (412, 915, 2.625),
            "pixel 8 pro": (448, 997, 3.0),
            "pixel 8": (412, 915, 2.625),
            "pixel 7": (412, 915, 2.625),
            "cph2449": (441, 986, 2.8125),
            "cph2581": (427, 953, 2.53125),
            "23049pcd8g": (393, 873, 2.75),
            "2311drk48g": (441, 981, 3.265),
        }
        model_match = re.search(
            r"\bAndroid\s+[\d.]+\s*;\s*([^;)]+?)(?:\s+Build/|;\s*wv\))",
            ua_str or "", re.I,
        )
        model_key = model_match.group(1).strip().lower() if model_match else ""
        width, height, dpr = android_profiles.get(
            model_key, (800, 1280, 2.0) if is_tablet else (412, 915, 2.625)
        )
        # Instagram carries physical resolution and density explicitly.
        ig_hw = re.search(
            r"Instagram\s+[\d.]+\s+Android\s+\([^;]+;\s*(\d+)dpi;\s*(\d+)x(\d+);",
            ua_str or "", re.I,
        )
        if ig_hw:
            dpr = int(ig_hw.group(1)) / 160.0
            width = round(int(ig_hw.group(2)) / dpr)
            height = round(int(ig_hw.group(3)) / dpr)
        viewport = {"width": width, "height": height}
        # 2026-06-14: device-coupled GPU + memory.
        webgl_vendor, webgl_renderer, hc, dm = _pick_android_gpu_from_ua(ua_str)
    elif os_key == "windows":
        platform = "Win32"
        vendor = "Google Inc."
        viewport = random.choice([
            {"width": 1920, "height": 1080},
            {"width": 1536, "height": 864},
            {"width": 1366, "height": 768},
            {"width": 1680, "height": 1050},
        ])
        dpr = random.choice([1.0, 1.25, 1.5])
        hc = random.choice([4, 8, 12, 16])
        dm = random.choice([4, 8, 16, 32])
        webgl_vendor = "Google Inc. (NVIDIA)"
        webgl_renderer = random.choice([
            "ANGLE (NVIDIA, NVIDIA GeForce GTX 1650 Direct3D11 vs_5_0 ps_5_0)",
            "ANGLE (NVIDIA, NVIDIA GeForce RTX 3060 Direct3D11 vs_5_0 ps_5_0)",
            "ANGLE (Intel, Intel(R) UHD Graphics 630 Direct3D11 vs_5_0 ps_5_0)",
            "ANGLE (AMD, AMD Radeon RX 6600 Direct3D11 vs_5_0 ps_5_0)",
        ])
    elif os_key == "macos":
        platform = "MacIntel"
        vendor = "Google Inc."
        viewport = random.choice([
            {"width": 1440, "height": 900},
            {"width": 1512, "height": 982},
            {"width": 1680, "height": 1050},
        ])
        dpr = 2
        hc = random.choice([8, 10, 12])
        dm = random.choice([8, 16])
        webgl_vendor = "Google Inc. (Apple)"
        webgl_renderer = random.choice([
            "ANGLE (Apple, Apple M1 Pro, OpenGL 4.1)",
            "ANGLE (Apple, Apple M2, OpenGL 4.1)",
            "ANGLE (Apple, Apple M3, OpenGL 4.1)",
        ])
    elif os_key == "linux":
        platform = "Linux x86_64"
        vendor = "Google Inc."
        viewport = {"width": 1920, "height": 1080}
        dpr = 1
        hc = random.choice([4, 8, 12])
        dm = random.choice([4, 8, 16])
        webgl_vendor = "Google Inc. (Intel)"
        webgl_renderer = "ANGLE (Intel, Mesa Intel(R) UHD Graphics 620)"
    else:
        platform = "Linux x86_64"
        vendor = "Google Inc."
        viewport = {"width": 1366, "height": 768}
        dpr = 1
        hc, dm = 4, 8
        webgl_vendor = "Google Inc."
        webgl_renderer = "ANGLE (Intel, Mesa Intel(R) HD Graphics)"

    if os_key not in ("android", "ios"):
        viewport = {
            "width": max(320, viewport["width"] + random.randint(-4, 4)),
            "height": max(568, viewport["height"] + random.randint(-8, 8)),
        }

    # ── 2026-01: extra fingerprint fields for deep anti-detect ──
    # All ADDITIVE — existing callers that only read the old keys are
    # unaffected. Values are realistic per-OS so MaxMind / IPQS / Anura
    # cannot fingerprint the headless-Chrome signature.
    chrome_major, _chrome_minor = _extract_chrome_version(ua_str)
    safari_major, _safari_minor = _extract_safari_version(ua_str)
    _plat_meta = _ua_platform_meta(os_key, ua_str)

    # Screen dimensions match viewport + realistic toolbar/taskbar.
    # Desktop OSs have a taskbar (~40-100px); mobile = viewport.
    if os_key == "windows":
        screen_w = max(1024, viewport["width"])
        screen_h = max(768, viewport["height"] + random.choice([40, 60, 80]))
        avail_w = screen_w
        avail_h = max(768, screen_h - random.choice([40, 48, 60]))  # taskbar
        outer_w_delta = 0  # outerWidth == innerWidth (window borders thin in modern Win)
        outer_h_delta = random.choice([74, 87, 117, 138])  # tab bar + URL bar + bookmarks
        color_depth = 24
        max_touch = 0
    elif os_key == "macos":
        screen_w = max(1280, viewport["width"])
        screen_h = max(800, viewport["height"] + random.choice([22, 25, 28]))
        avail_w = screen_w
        avail_h = max(800, screen_h - random.choice([22, 25, 28]))  # menu bar
        outer_w_delta = 0
        outer_h_delta = random.choice([74, 87, 105, 130])
        color_depth = 30 if dpr >= 2 else 24
        max_touch = 0
    elif os_key == "linux":
        screen_w = max(1024, viewport["width"])
        screen_h = max(768, viewport["height"] + random.choice([24, 40, 60]))
        avail_w = screen_w
        avail_h = max(768, screen_h - random.choice([24, 40]))
        outer_w_delta = 0
        outer_h_delta = random.choice([74, 100, 130])
        color_depth = 24
        max_touch = 0
    elif os_key == "android":
        screen_w = viewport["width"]
        screen_h = viewport["height"]
        avail_w = viewport["width"]
        avail_h = viewport["height"]
        outer_w_delta = 0
        outer_h_delta = 0
        color_depth = 24
        max_touch = random.choice([5, 10])
    elif os_key == "ios":
        screen_w = viewport["width"]
        screen_h = viewport["height"]
        avail_w = viewport["width"]
        avail_h = viewport["height"]
        outer_w_delta = 0
        outer_h_delta = 0
        color_depth = 24
        max_touch = 5
    else:
        screen_w = max(1024, viewport["width"])
        screen_h = max(768, viewport["height"] + 40)
        avail_w = screen_w
        avail_h = screen_h - 40
        outer_w_delta = 0
        outer_h_delta = 80
        color_depth = 24
        max_touch = 0

    # Network Information API — realistic per-device-type effective type
    if os_key in ("android", "ios"):
        effective_type = random.choice(["4g", "4g", "4g", "3g"])  # mostly 4g
        downlink = round(random.uniform(2.5, 10.0), 1)
        rtt = random.choice([50, 100, 150, 200, 300])
        connection_type = "cellular"
    else:
        effective_type = "4g"
        downlink = round(random.uniform(5.0, 20.0), 1)
        rtt = random.choice([25, 50, 75, 100])
        connection_type = "wifi"

    # Battery API — realistic snapshot. Mobile usually mid-charge,
    # desktop often plugged in.
    if os_key in ("android", "ios"):
        battery_level = round(random.uniform(0.18, 0.92), 2)
        battery_charging = random.random() < 0.35  # 35% plugged-in chance
    else:
        battery_level = round(random.uniform(0.45, 0.98), 2)
        battery_charging = random.random() < 0.7  # 70% plugged in for desktop

    webgl_vendor, webgl_renderer = _sanitize_swiftshader_webgl(
        os_key, webgl_vendor, webgl_renderer,
    )

    locale_match = re.search(
        r"\b(?:ByteFullLocale|ByteLocale)/([A-Za-z]{2}(?:[-_][A-Za-z]{2})?)\b",
        ua_str or "",
    )
    if not locale_match:
        locale_match = re.search(
            r"\bInstagram\s+[\d.]+.*?;\s*([a-z]{2}[_-][A-Z]{2})\s*;",
            ua_str or "", re.I,
        )
    explicit_locale = locale_match.group(1).replace("_", "-") if locale_match else ""

    canvas_seed = random.randint(1, 2**30)
    is_chromium_ua = bool(re.search(r"(?:Chrome|CriOS|Chromium)/", ua_str or "", re.I))
    history_length = 2 + (canvas_seed % 4)  # deterministic 2-5 from seed

    return {
        "os": os_key,
        "platform": platform,
        "vendor": vendor,
        "viewport": viewport,
        "device_scale_factor": dpr,
        "is_mobile": is_mobile or is_tablet or os_key in ("android", "ios"),
        "has_touch": is_mobile or is_tablet or os_key in ("android", "ios"),
        "hardware_concurrency": hc,
        "device_memory": dm,
        "webgl_vendor": webgl_vendor,
        "webgl_renderer": webgl_renderer,
        # Canvas noise seed — unique per visit so canvas fingerprint differs too
        "canvas_seed": canvas_seed,
        "label": f"{(ua.os.family + ' ' + ua.os.version_string) if ua else os_key}".strip() or ua_str[:40],
        # ── 2026-01 additions ──
        "chrome_version": chrome_major,
        "chrome_full_version": _extract_chrome_full_version(ua_str),
        "platform_version": _plat_meta["platform_version"],
        "ua_architecture": _plat_meta["architecture"],
        "ua_model": _plat_meta["ua_model"],
        "safari_version": safari_major,
        "audio_seed": random.randint(1, 2**30),
        "font_seed": random.randint(1, 2**30),
        "screen_width": screen_w,
        "screen_height": screen_h,
        "avail_width": avail_w,
        "avail_height": avail_h,
        "outer_width_delta": outer_w_delta,
        "outer_height_delta": outer_h_delta,
        "color_depth": color_depth,
        "max_touch_points": max_touch,
        "effective_type": effective_type,
        "downlink": downlink,
        "rtt": rtt,
        "connection_type": connection_type,
        "battery_level": battery_level,
        "battery_charging": battery_charging,
        # On Linux hosts, claiming Windows/macOS exclusive fonts (Segoe UI,
        # Helvetica Neue, …) is a metrics mismatch — use the Linux set.
        "fonts": (
            _OS_FONTS["linux"]
            if __import__("sys").platform.startswith("linux") and os_key in ("windows", "macos")
            else _OS_FONTS.get(os_key, _OS_FONTS["windows"])
        ),
        "explicit_locale": explicit_locale,
        "client_hints": client_hint_headers_for_ua(ua_str),
        "is_chromium_ua": is_chromium_ua,
        "history_length": history_length,
    }


def _sync_fingerprint_to_ua(
    ua: str,
    fp: Optional[Dict[str, Any]] = None,
    identity_label: str = "",
) -> Dict[str, Any]:
    """Rebuild fingerprint after UA coercion so viewport / CH / WebGL match."""
    new_fp = _fingerprint_from_ua(ua)
    if identity_label:
        try:
            from anti_detect_v230 import align_webgl_to_ua_deterministic as _align_wgl
            _wgl = _align_wgl(ua, identity_label)
            new_fp["webgl_vendor"] = _wgl["vendor"]
            new_fp["webgl_renderer"] = _wgl["renderer"]
        except Exception:
            pass
    elif fp:
        # Preserve deterministic canvas seed when UA tweak didn't change OS family.
        try:
            if fp.get("canvas_seed") and new_fp.get("os") == fp.get("os"):
                new_fp["canvas_seed"] = fp["canvas_seed"]
        except Exception:
            pass
    return new_fp


async def _rut_apply_context_stealth(
    context,
    *,
    fp: Dict[str, Any],
    geo: Dict[str, Any],
    ua: str,
    platform: str = "",
    ctx_headers: Optional[Dict[str, str]] = None,
    fp_hash_override: Optional[int] = None,
    identity_label: str = "",
    skip_natural_canvas: bool = False,
    skip_webgl_align: bool = False,
    fingerprint_win: bool = True,
    cloak_quiet: bool = False,
) -> bool:
    """Full RUT stealth stack — shared by main, context-retry, tunnel-retry paths.

    Returns True on success. On hard failure sets `context._krx_stealth_degraded`
    and returns False (or re-raises for the initial stealth script build).
    """
    try:
        await context.add_init_script(
            _build_stealth_script(
                fp, geo, fp_hash_override=fp_hash_override, skip_canvas_noise=True,
            )
        )
    except Exception as _stealth_err:
        try:
            context._krx_stealth_degraded = True
        except Exception:
            pass
        logger.warning(f"stealth script inject failed: {_stealth_err}")
        raise

    try:
        from anti_detect_v230 import (
            align_webgl_to_ua_deterministic as _align_webgl,
            natural_canvas_js as _natural_canvas,
            webgl_align_js as _webgl_align_js,
        )
        _wgl: Dict[str, Any] = {}
        if not skip_webgl_align:
            if identity_label:
                _wgl = _align_webgl(ua, identity_label)
            elif fp.get("webgl_vendor") and fp.get("webgl_renderer"):
                _wgl = {
                    "vendor": fp["webgl_vendor"],
                    "renderer": fp["webgl_renderer"],
                    "gpu_family": fp.get("gpu_family", ""),
                }
        # Canvas noise / natural canvas
        # Legacy RUT: natural canvas only when WebGL cfg present.
        # Profile modes may skip WebGL align while still wanting canvas noise.
        # v2.7.20 — Cloak quiet: skip natural canvas (C++ kernel owns it)
        if cloak_quiet:
            skip_natural_canvas = True
        if not skip_natural_canvas and (
            bool(_wgl.get("vendor") and _wgl.get("renderer")) or skip_webgl_align
        ):
            if "canvas_seed" in fp and fp.get("canvas_seed") is not None:
                _seed = int(fp.get("canvas_seed") or 0)
            else:
                _seed = random.randint(1, 2**30)
            if _seed > 0:
                try:
                    await context.add_init_script(_natural_canvas(_seed))
                except Exception as _nc_err:
                    logger.warning(
                        f"natural_canvas inject failed ({_nc_err}) — "
                        f"falling back to stealth canvas noise"
                    )
                    try:
                        await context.add_init_script(
                            _build_stealth_script(
                                fp, geo, fp_hash_override=fp_hash_override,
                                skip_canvas_noise=False,
                            )
                        )
                    except Exception as _fb_err:
                        try:
                            context._krx_stealth_degraded = True
                        except Exception:
                            pass
                        logger.warning(f"stealth canvas fallback also failed: {_fb_err}")
                        return False
        if _wgl.get("vendor") and _wgl.get("renderer"):
            await context.add_init_script(_webgl_align_js(_wgl))
    except Exception as _wgl_err:
        logger.debug(f"WebGL/canvas stealth inject failed: {_wgl_err}")
        try:
            context._krx_stealth_degraded = True
        except Exception:
            pass
        return False
    try:
        from anti_detect_v230 import apply_v230_stealth as _v230_apply
        _vp = dict(fp.get("viewport") or {"width": 1920, "height": 1080})
        if fp.get("device_scale_factor") is not None:
            _vp["device_scale_factor"] = fp["device_scale_factor"]
        _v230_r = await _v230_apply(
            context,
            ua=ua,
            viewport=_vp,
            platform=platform or "",
        )
        _v_hdrs = _v230_r.get("headers") or {}
        if _v_hdrs:
            _cur = dict(_v_hdrs)
            _cur.update(ctx_headers or {})
            await context.set_extra_http_headers(_cur)
    except Exception as _v230_err:
        logger.warning(f"v2.3.0 stealth apply failed (continuing): {_v230_err}")

    # v2.7.20 — CreepJS-class Fingerprint WIN pack (iframe/Worker/OffscreenCanvas/chrome)
    if fingerprint_win:
        try:
            from fingerprint_win import build_fingerprint_win_js

            _fh = int(fp_hash_override) if fp_hash_override is not None else 0
            await context.add_init_script(
                build_fingerprint_win_js(
                    fp,
                    cloak_mode=bool(cloak_quiet),
                    fp_hash=_fh,
                )
            )
        except Exception as _fw_err:
            logger.debug(f"fingerprint_win inject skipped: {_fw_err}")

    return not bool(getattr(context, "_krx_stealth_degraded", False))


_UNFILLED_MACRO_URL_RX = __import__("re").compile(r"\{\{[^}]+\}\}|%7[bB]%7[bB]")


# Telemetry queue (job_id → list of macro-leak records) consumed at
# job-finalise time and flushed into MongoDB `rut_diagnostics`. We keep
# it in-memory during the run so the route handler stays non-blocking
# and we don't need to pass the Mongo handle through Playwright closures.
_MACRO_LEAK_BUFFER: Dict[str, List[Dict[str, Any]]] = {}
# Stuck-visit buffer (job_id → list of stuck-event records). Same flush
# semantics as the macro-leak buffer.
_STUCK_EVENT_BUFFER: Dict[str, List[Dict[str, Any]]] = {}


def _record_macro_leak(job_id: str, visit_index: int, url: str, resource_type: str) -> None:
    """Append a macro-leak event to the in-memory buffer. Called from the
    route handler — must stay sync + non-throwing so a Playwright handler
    error never crashes the visit."""
    try:
        buf = _MACRO_LEAK_BUFFER.setdefault(job_id, [])
        if len(buf) >= 200:  # cap per-job to avoid runaway memory
            return
        buf.append({
            "job_id": job_id,
            "visit_index": int(visit_index or 0),
            "blocked_url": (url or "")[:1024],
            "resource_type": (resource_type or "")[:32],
            "timestamp": datetime.now(timezone.utc).isoformat(),
        })
    except Exception:
        pass


def _record_stuck_event(job_id: str, visit_index: int, url: str, seconds_stuck: float,
                       last_step: int = -1, snapshot_name: str = "",
                       body_snippet: str = "") -> None:
    """Append a stuck-visit event. Called by the per-visit watchdog when
    the page URL hasn't changed for the configured threshold."""
    try:
        buf = _STUCK_EVENT_BUFFER.setdefault(job_id, [])
        if len(buf) >= 200:
            return
        buf.append({
            "job_id": job_id,
            "visit_index": int(visit_index or 0),
            "stuck_url": (url or "")[:1024],
            "seconds_stuck": round(float(seconds_stuck or 0), 1),
            "last_step_index": int(last_step) if last_step is not None else -1,
            "snapshot_name": (snapshot_name or "")[:128],
            "body_snippet": (body_snippet or "")[:2000],
            "timestamp": datetime.now(timezone.utc).isoformat(),
        })
    except Exception:
        pass


async def _stuck_watchdog(page, job_id: str, visit_index: int,
                          threshold_s: float = 240.0, poll_s: float = 5.0,
                          shots_dir=None, on_stuck=None,
                          state: Optional[Dict[str, Any]] = None) -> None:
    """Watch the page while a visit's automation steps are running. If
    the page hasn't progressed for `threshold_s` seconds we consider
    the visit stuck and:
        1. Capture a screenshot + first 2 KB of body text (debug aid).
        2. Emit `_record_stuck_event` so the operator can see WHICH page
           the job dies on.
        3. Invoke the `on_stuck` callback (if provided) — typically the
           visit loop's `steps_task.cancel()` so the run doesn't waste
           the rest of its automation budget on a dead page.
    We only record ONCE per stuck-period so a 5-minute hang doesn't
    generate 12 identical rows.

    2026-01: default threshold raised from 25s → 60s so that legitimate
    long form-submit sequences (form fill + Continue + cascading
    wait_for_load steps that can total 25-30s of intentional waiting)
    don't get killed prematurely.

    2026-05: default raised again from 60s → 240s (4 min) for slow
    survey-style offer pages (e.g. anyunclaimedassets.com/indexform.php)
    where multi-step SPA transitions + form-fill + submit + thank-you
    redirect can legitimately take 90-180s end-to-end. The
    chrome-error:// fast-path below still fires INSTANTLY (no wait) so
    dead proxies / DNS failures / SSL errors are still caught
    immediately — only the "page is alive but slow" case gets the
    extended budget.

    2026-01 (revised): "Progress" is now defined as EITHER the main-frame
    URL changing OR the DOM-progress fingerprint changing (body text
    length, body child count, document title, location hash). This is
    essential for offers running as single-page apps (SPAs) — e.g.
    anyunclaimedassets.com/indexform.php, which transitions through
    Profile → Cash & Assets Survey → Benefits → Thank-you ALL on the
    same URL via JavaScript. The old URL-only watchdog killed every
    such visit at 60s even though the DOM was progressing through
    multiple survey steps. Now we only abort if BOTH the URL and the
    DOM fingerprint stay frozen for the full threshold."""
    # Cheap "is the page progressing?" signal — combines URL + a handful
    # of DOM characteristics that change on any meaningful UI transition
    # (route, modal open, new survey question rendered). Computing this
    # is one Playwright evaluate call (single round-trip) instead of a
    # full innerHTML snapshot, keeping per-poll cost ~10 ms.
    #
    # ── 2026-05 (improved sensitivity) ──
    # Issue: survey-style SPAs (e.g. anyunclaimedassets indexform.php)
    # swap question text WITHOUT changing length / node count appreciably,
    # so the bot's automation was progressing but the watchdog couldn't
    # see it and killed the visit at 60s. Fixes:
    #   1. Add a fast 32-bit FNV-1a hash of body.innerText — detects ANY
    #      content change even if length stays constant.
    #   2. Add `location.search` (query string) — many SPAs encode step
    #      in `?step=3` etc.
    #   3. Add visible button/input count — survey transitions usually
    #      add/remove form controls.
    #   4. Add the FIRST 80 chars of trimmed innerText so a quick eyeball
    #      shows the actual screen content the watchdog sees.
    # Any change in any of these signals resets the stuck timer.
    _PROGRESS_JS = (
        "()=>{try{"
        "var b=document.body;"
        "var raw=(b&&b.innerText)?b.innerText:'';"
        "var t=raw.length;"
        "var c=(b&&b.children)?b.children.length:0;"
        "var d=(b&&b.querySelectorAll)?b.querySelectorAll('*').length:0;"
        # FNV-1a 32-bit hash — fast, deterministic, no deps
        "var h=2166136261;"
        "for(var i=0;i<raw.length;i++){h^=raw.charCodeAt(i);h=(h*16777619)>>>0;}"
        # Visible interactive control count
        "var ctrls=0;"
        "try{"
        " var sel=b?b.querySelectorAll('button,a[href],input,select,textarea,[role=button]'):[];"
        " for(var k=0;k<sel.length;k++){"
        "  var el=sel[k];"
        "  var s=window.getComputedStyle(el);"
        "  if(s&&s.display!=='none'&&s.visibility!=='hidden'&&el.offsetWidth>0&&el.offsetHeight>0)ctrls++;"
        " }"
        "}catch(_e){}"
        "var snip=(raw||'').replace(/\\s+/g,' ').trim().slice(0,80);"
        "return [document.title||'',(location.hash||''),(location.search||''),t,c,d,h>>>0,ctrls,snip];"
        "}catch(e){return ['','','',0,0,0,0,0,''];}}"
    )

    async def _probe():
        try:
            return await asyncio.wait_for(page.evaluate(_PROGRESS_JS), timeout=2.0)
        except Exception:
            return None

    last_url = ""
    try:
        last_url = page.url or ""
    except Exception:
        pass
    last_progress = await _probe()
    last_changed_at = __import__("time").monotonic()
    recorded_this_period = False
    # 2026-05: track progression so the caller can distinguish between
    # "page never moved" (truly dead) vs "page progressed then went idle"
    # (submit succeeded, just no more user-driven steps). state is a
    # shared dict the caller can read AFTER the watchdog fires.
    progression_count = 0
    if state is not None:
        state.setdefault("progressed", False)
        state.setdefault("progression_count", 0)
    while True:
        try:
            await asyncio.sleep(poll_s)
        except asyncio.CancelledError:
            return
        try:
            cur = page.url or ""
        except Exception:
            return
        now = __import__("time").monotonic()
        # ── Fast path: chrome-error:// means the tab died mid-flight
        #    (proxy tunnel dropped, DNS lookup failed, SSL error, etc.).
        #    Don't wait for the full 25s threshold — fire the stuck
        #    record + abort callback immediately so the run can move on.
        if cur.startswith("chrome-error://") or cur.startswith("chrome://network-error"):
            if not recorded_this_period:
                _record_stuck_event(
                    job_id, visit_index, cur,
                    max(0.0, now - last_changed_at),
                    snapshot_name="",
                    body_snippet="(chrome-error fast-path — no DOM to capture)",
                )
                recorded_this_period = True
                try:
                    push_live_step(
                        job_id, visit_index, "stuck", "warn",
                        f"Chrome error page detected ({cur[:60]}) — aborting visit",
                    )
                except Exception:
                    pass
                if on_stuck is not None:
                    try:
                        on_stuck()
                    except Exception:
                        pass
                return
        # Did the URL change?
        _url_changed = cur != last_url
        if _url_changed:
            last_url = cur
            last_changed_at = now
            recorded_this_period = False
            last_progress = await _probe()
            progression_count += 1
            if state is not None:
                state["progressed"] = True
                state["progression_count"] = progression_count
            continue
        # URL is unchanged — check DOM-progress fingerprint. If it
        # moved (different title / hash / search / text-content-hash /
        # body-text length / child count / total node count / visible
        # controls count), the page IS progressing (SPA transition,
        # survey question rendered, etc.) and we reset the stuck timer.
        # ── 2026-05 ──
        # New tuple layout: [title, hash, search, text_len, child, node,
        # text_hash, ctrls, snip]
        cur_progress = await _probe()
        if cur_progress is not None and last_progress is not None:
            try:
                _title_chg = cur_progress[0] != last_progress[0]
                _hash_chg = cur_progress[1] != last_progress[1]
                _search_chg = (
                    cur_progress[2] != last_progress[2]
                    if len(cur_progress) > 2 and len(last_progress) > 2
                    else False
                )
                _text_delta = abs(int(cur_progress[3]) - int(last_progress[3])) if len(cur_progress) > 3 else 0
                _child_delta = abs(int(cur_progress[4]) - int(last_progress[4])) if len(cur_progress) > 4 else 0
                _node_delta = abs(int(cur_progress[5]) - int(last_progress[5])) if len(cur_progress) > 5 else 0
                _text_hash_chg = (
                    int(cur_progress[6]) != int(last_progress[6])
                    if len(cur_progress) > 6 and len(last_progress) > 6
                    else False
                )
                _ctrls_chg = (
                    int(cur_progress[7]) != int(last_progress[7])
                    if len(cur_progress) > 7 and len(last_progress) > 7
                    else False
                )
                _dom_changed = (
                    _title_chg or _hash_chg or _search_chg
                    or _text_hash_chg                  # ANY content change (even same length)
                    or _ctrls_chg                      # form controls added/removed
                    or _text_delta >= 1                # 2026-05: lowered from 4 — even single-char delta resets
                    or _child_delta >= 1
                    or _node_delta >= 1                # 2026-05: lowered from 3 — any DOM node add/remove resets
                )
            except Exception:
                _dom_changed = False
            if _dom_changed:
                last_progress = cur_progress
                last_changed_at = now
                recorded_this_period = False
                progression_count += 1
                if state is not None:
                    state["progressed"] = True
                    state["progression_count"] = progression_count
                continue
        elif cur_progress is not None:
            # First successful probe — seed the baseline so the next
            # iteration can detect deltas.
            last_progress = cur_progress
        elapsed = now - last_changed_at
        # Smart Funnel / automation heartbeat — engine reports activity even
        # when DOM hash is unchanged between deal-wall polls.
        if state is not None:
            try:
                hb = float(state.get("heartbeat_at") or 0)
            except (TypeError, ValueError):
                hb = 0.0
            if hb and (now - hb) < max(poll_s * 4, 20.0):
                last_changed_at = now
                recorded_this_period = False
                state["progressed"] = True
                continue
        if elapsed >= threshold_s and not recorded_this_period:
            # ── Capture debug artefacts BEFORE aborting ────────────────
            snapshot_name = ""
            body_snippet = ""
            try:
                if shots_dir is not None:
                    sp = Path(str(shots_dir)) / f"visit_{int(visit_index):05d}_stuck.png"
                    await asyncio.wait_for(
                        page.screenshot(path=str(sp), full_page=True),
                        timeout=5.0,
                    )
                    snapshot_name = sp.name
            except Exception:
                pass
            try:
                body_snippet = await asyncio.wait_for(
                    page.evaluate(
                        "() => (document.body && document.body.innerText) "
                        "? document.body.innerText.slice(0, 2000) : ''"
                    ),
                    timeout=4.0,
                ) or ""
            except Exception:
                body_snippet = ""

            _record_stuck_event(
                job_id, visit_index, cur, elapsed,
                snapshot_name=snapshot_name,
                body_snippet=body_snippet,
            )
            recorded_this_period = True
            try:
                push_live_step(
                    job_id, visit_index, "stuck", "warn",
                    f"Visit stuck on {cur[:120]} for ~{int(elapsed)}s (URL+DOM frozen) — aborting + see diagnostics",
                )
            except Exception:
                pass
            # ── Fire the abort callback so the visit loop can cancel
            #    the automation steps task and move on to the next visit.
            #    Then exit the watchdog (parent will await us).
            if on_stuck is not None:
                try:
                    on_stuck()
                except Exception:
                    pass
            return




def _make_macro_guard(
    job_id: str,
    visit_index: int,
    force_referer: str = "",
    target_url: str = "",
    click_once_guard: Optional[Dict[str, Any]] = None,
):
    """Return a Playwright route handler closure bound to this visit's
    `(job_id, visit_index)` so the macro-leak telemetry record contains
    the right context. Returned handler is `async def`.

    2026-02 v2.6.13 — `force_referer` support:
        When a custom Referer URL is configured for the job (Custom URL
        mode + optional preset), Chromium's default referrer-policy
        strips the Referer to just the origin on cross-origin redirects
        (tracker → offer). This surfaced as the customer report where
        13/17 clicks arrived at the affiliate with an EMPTY Referer
        column even though "Custom URL (same for every visit)" +
        `https://getstimulus.ai/` were configured.

        Setting `force_referer` makes this handler unconditionally inject
        the configured Referer header on EVERY top-level document
        navigation for THIS visit — the initial tracker request AND
        every redirect follow-up. This survives `Referrer-Policy:
        no-referrer` responses from intermediate hops, giving the
        affiliate a consistent Referer column across all visits.

        `target_url` is stored for future use (e.g. skipping the force
        on requests to origins we don't own); currently we force on
        every document navigation because it's the safest default —
        real browsers DO carry the last-known Referer through their
        entire redirect chain when their referrer-policy is
        `unsafe-url` (many social platforms explicitly set this).
    """
    async def _handler(route, request):
        try:
            url = request.url or ""
            if _UNFILLED_MACRO_URL_RX.search(url):
                try:
                    rtype = (request.resource_type or "").lower()
                except Exception:
                    rtype = ""
                _record_macro_leak(job_id, visit_index, url, rtype)
                if rtype == "document":
                    try:
                        await route.fulfill(
                            status=200,
                            content_type="text/html",
                            body=(
                                "<!doctype html><html><head><meta charset='utf-8'>"
                                "<title>blocked</title></head><body>"
                                "<script>try{history.back();}catch(e){}</script>"
                                "</body></html>"
                            ),
                        )
                    except Exception:
                        try:
                            await route.abort()
                        except Exception:
                            pass
                else:
                    try:
                        await route.abort()
                    except Exception:
                        pass
                return

            # After the first tracker/offer document GET, abort any later
            # hit on that same click URL (CTA <a href>, deal aff_c, goto,
            # reload, pixel). Form/survey/deals stay on the already-open page.
            # v2.6.96: also check against the FINAL offer URL (after tracker
            # redirect) AND any URL with aff_c/offer_id params that would
            # register another Affise click.
            if click_once_guard and click_once_guard.get("fired"):
                _should_abort = False
                orig = str(click_once_guard.get("click_url") or target_url or "")
                if orig and _is_repeat_offer_click(url, orig):
                    _should_abort = True
                if not _should_abort:
                    offer_orig = str(click_once_guard.get("offer_url") or "")
                    if offer_orig and _is_repeat_offer_click(url, offer_orig):
                        _should_abort = True
                if not _should_abort and _url_has_affiliate_click_params(url):
                    try:
                        _rtype_chk = (request.resource_type or "").lower()
                    except Exception:
                        _rtype_chk = "document"
                    if _rtype_chk == "document":
                        _should_abort = True
                if _should_abort:
                    try:
                        await route.abort()
                    except Exception:
                        try:
                            await route.continue_()
                        except Exception:
                            pass
                    return

            # 2026-02 v2.6.13 — Referer force-injection for document
            # navigations. Only applies when `force_referer` was set for
            # this visit AND the request is a top-level navigation
            # (main_frame document). Sub-resource requests (images, JS,
            # XHR, etc.) inherit the page-level Referer automatically
            # via Chromium's own referrer-policy engine, so we don't
            # need to touch them.
            if force_referer:
                try:
                    rtype = (request.resource_type or "").lower()
                except Exception:
                    rtype = ""
                if rtype == "document":
                    try:
                        _hdrs = dict(request.headers or {})
                        # Playwright normalises header keys to lower-case.
                        # Set both `referer` (Chromium expects lower-case
                        # per HTTP/2 spec) and remove any conflicting
                        # capitalised variant that might have been added.
                        _hdrs.pop("Referer", None)
                        _hdrs["referer"] = force_referer
                        _req_ua = _hdrs.get("user-agent") or _hdrs.get("User-Agent") or ""
                        _hdrs = _apply_contract_client_hints(_hdrs, _req_ua)
                        await route.continue_(headers=_hdrs)
                        return
                    except Exception:
                        # Any failure here MUST fall back to the default
                        # continue below — never break a visit because
                        # of referer-injection edge cases.
                        pass

            try:
                _req_ua = request.headers.get("user-agent") or request.headers.get("User-Agent") or ""
                _hdrs = _apply_contract_client_hints(dict(request.headers or {}), _req_ua)
                if _hdrs != dict(request.headers or {}):
                    await route.continue_(headers=_hdrs)
                    return
            except Exception:
                pass

            await route.continue_()
        except Exception:
            try:
                await route.continue_()
            except Exception:
                pass
    return _handler


async def _block_unfilled_macro_request(route, request) -> None:
    """Abort any request whose URL still contains an unfilled tracker
    macro like `{{ccpa}}`, `{{sub_id}}`, etc.

    Affiliate landing pages frequently embed CCPA / opt-out / privacy
    anchors with macro placeholders the tracker is expected to replace
    server-side. When the inbound tracker URL is missing the macro, the
    literal `{{...}}` leaks into the rendered HTML and any aggressive
    "force-navigation" JS step in the user's automation script can end
    up clicking it, dead-ending the visit on a 404. Killing those
    navigations at the network layer keeps the page on the legitimate
    flow URL so subsequent form-fill / answer-click steps still run.

    For top-level document navigations we cannot just `route.abort()`
    because that leaves Chrome on `chrome-error://chromewebdata/`. We
    instead fulfill the request with a tiny HTML that calls
    `history.back()` so the browser returns to the legitimate offer
    page and the automation can resume from there.

    NOTE: This generic handler does NOT record telemetry — used by demo
    scripts only. Production visits use `_make_macro_guard(job_id, idx)`
    so each blocked request is logged against the originating job.
    """
    try:
        url = request.url or ""
        if _UNFILLED_MACRO_URL_RX.search(url):
            try:
                rtype = (request.resource_type or "").lower()
            except Exception:
                rtype = ""
            if rtype == "document":
                # Fulfill with a back-nav stub so we don't blank the tab.
                try:
                    await route.fulfill(
                        status=200,
                        content_type="text/html",
                        body=(
                            "<!doctype html><html><head><meta charset='utf-8'>"
                            "<title>blocked</title></head><body>"
                            "<script>try{history.back();}catch(e){}</script>"
                            "</body></html>"
                        ),
                    )
                except Exception:
                    try:
                        await route.abort()
                    except Exception:
                        pass
            else:
                try:
                    await route.abort()
                except Exception:
                    pass
            return
        await route.continue_()
    except Exception:
        try:
            await route.continue_()
        except Exception:
            pass



# ─── Proxy helpers ───────────────────────────────────────────────
def _parse_proxy_line(line: str) -> Optional[Dict[str, Any]]:
    s = (line or "").strip()
    if not s:
        return None
    scheme = "http"
    if s.startswith("http://"):
        s = s[7:]
    elif s.startswith("https://"):
        s = s[8:]
        scheme = "https"
    user, pwd = None, None
    if "@" in s:
        auth, s = s.rsplit("@", 1)
        if ":" in auth:
            user, pwd = auth.split(":", 1)
        else:
            user = auth
    parts = s.split(":")
    if len(parts) == 2:
        host, port = parts
    elif len(parts) == 4:
        host, port, user, pwd = parts
    else:
        return None
    try:
        int(port)
    except ValueError:
        return None
    out: Dict[str, Any] = {"server": f"{scheme}://{host}:{port}", "raw": line.strip()}
    if user:
        out["username"] = user
    if pwd:
        out["password"] = pwd
    # 2026-02 v2.6.14 — mark rotating-gateway lines so
    # `no_repeated_proxy` does not treat the gateway URL as a single-use
    # proxy. A rotating gateway (DataImpulse, Oxylabs, Bright Data,
    # IPRoyal, Soax, Smartproxy, Webshare, Luminati) returns a
    # DIFFERENT exit IP per TCP session — the URL itself is meant to be
    # dialled over and over. The "Strict unique IP" toggle already
    # handles IP-level uniqueness via `_probe_proxy_geo`, so we don't
    # need URL-level suppression for these providers.
    out["is_rotating_gateway"] = _detect_rotating_gateway(host, user or "")
    return out


# 2026-02 v2.6.14 — signature list for well-known rotating gateways.
# When a proxy line's hostname or username matches any of these, we
# treat the URL as re-dialable (each new connection = new exit IP).
_ROTATING_GATEWAY_HOSTS = (
    "dataimpulse.com",
    "oxylabs.io",
    "brightdata.com", "superproxy.io", "brd.superproxy.io", "lum-superproxy.io",
    "iproyal.com",
    "soax.com",
    "smartproxy.com", "smartproxy.net", "decodo.com",
    "webshare.io",
    "packetstream.io",
    "geosurf.io",
    "shifter.io",
    "netnut.io",
    "rayobyte.com",
    "storm.io", "stormproxies.com",
    "proxyempire.io",
    "nimbleway.com",
    "asocks.com",
    "infatica.io",
    "proxy-cheap.com",
    "proxysale.com",
    "ipburger.com",
    "hydraproxy.com",
    "ip2world.com",
    "spaceproxy.net",
    "abcproxy.com",
    "kocerroxy.com",
    "922proxy.com",
    "9proxy.com",
    "coronium.io",
    "pyproxy.com",
)

_ROTATING_GATEWAY_HOST_PREFIXES = (
    "gw.", "gate.", "pr.", "residential.", "rotating.", "rotate.",
    "isp.", "sticky.", "proxy.", "gateway.",
)

_ROTATING_GATEWAY_USER_MARKERS = (
    "sessid", "session-", "session_", "sess-", "sess_",
    "session=", "sessid=", "-session-", "_session_",
    "rotating", "sticky", "sticky-",
)

def _detect_rotating_gateway(host: str, username: str) -> bool:
    """Return True if the (host, username) pair looks like a rotating
    gateway URL. Used by _parse_proxy_line + pick_next_proxy so the
    `no_repeated_proxy` guard does not lock the operator out of their
    own gateway after a single visit."""
    host_l = (host or "").strip().lower()
    user_l = (username or "").strip().lower()
    if not host_l:
        return False
    # Well-known provider domain match (suffix).
    for dom in _ROTATING_GATEWAY_HOSTS:
        if host_l == dom or host_l.endswith("." + dom):
            return True
    # Common gateway hostname prefix.
    for pfx in _ROTATING_GATEWAY_HOST_PREFIXES:
        if host_l.startswith(pfx):
            return True
    # Username-embedded session/rotation markers.
    if user_l:
        for marker in _ROTATING_GATEWAY_USER_MARKERS:
            if marker in user_l:
                return True
    return False


def _host_from_proxy_server(server: str) -> str:
    """Extract hostname from a proxy server URL (http://user:pass@host:port)."""
    try:
        from urllib.parse import urlparse
        return (urlparse(server or "").hostname or "").strip()
    except Exception:
        return ""


def _is_smartproxy_gateway_host(host: str) -> bool:
    """True for Decodo / Smartproxy gateway hosts (incl. proxy.smartproxy.net)."""
    h = (host or "").strip().lower()
    if not h:
        return False
    return any(
        needle in h
        for needle in (
            "decodo.com",
            "smartproxy.com",
            "smartproxy.net",
            "smart-proxy.com",
        )
    )


async def _enrich_geo_from_exit_ip(result: Dict[str, Any]) -> None:
    """Fill region/country when a minimal probe returned only the exit IP."""
    ip = (result.get("exit_ip") or "").strip()
    if not ip:
        return
    if result.get("region") and result.get("country"):
        return
    try:
        async with httpx.AsyncClient(timeout=httpx.Timeout(8.0, connect=5.0)) as direct:
            r = await direct.get(
                f"http://ip-api.com/json/{ip}"
                "?fields=status,country,countryCode,region,regionName,city,"
                "timezone,lat,lon,proxy,hosting,isp,org,as,asname,mobile"
            )
            if r.status_code != 200:
                return
            data = r.json() or {}
            if data.get("status") != "success":
                return
            result["country_name"] = data.get("country") or result.get("country_name")
            result["country"] = data.get("countryCode") or result.get("country")
            result["region"] = data.get("region") or result.get("region")
            result["region_name"] = data.get("regionName") or result.get("region_name")
            result["city"] = data.get("city") or result.get("city")
            try:
                result["lat"] = float(data.get("lat") or result.get("lat") or 0)
                result["lon"] = float(data.get("lon") or result.get("lon") or 0)
            except (TypeError, ValueError):
                pass
            result["timezone"] = data.get("timezone") or result.get("timezone")
            result["isp"] = data.get("isp") or result.get("isp") or ""
            result["org"] = data.get("org") or result.get("org") or ""
            result["as_name"] = data.get("as") or data.get("asname") or result.get("as_name") or ""
            if data.get("proxy") or data.get("hosting"):
                result["is_vpn"] = True
    except Exception as e:
        logger.debug(f"exit-IP geo enrich failed for {ip}: {e}")


def _proxy_url_scheme_variants(proxy_url: str) -> List[str]:
    """Try both http:// and https:// proxy schemes — some gateways accept only one."""
    url = (proxy_url or "").strip()
    if not url:
        return []
    out = [url]
    if url.startswith("http://"):
        alt = "https://" + url[len("http://"):]
        if alt not in out:
            out.append(alt)
    elif url.startswith("https://"):
        alt = "http://" + url[len("https://"):]
        if alt not in out:
            out.append(alt)
    return out


def _proxy_url_for_http(proxy: Dict[str, Any]) -> str:
    """Build a single proxy URL for httpx/curl from a Krexion proxy dict.

    Accepts the canonical shape from `_parse_proxy_line`:
      server=http://host:port, username=..., password=...
    If `server` already embeds credentials (legacy/raw lines), returns
    it unchanged — never double-embeds auth (that breaks every probe).
    """
    from urllib.parse import quote

    server = (proxy.get("server") or "").strip()
    if not server:
        return ""
    if "://" not in server:
        server = f"http://{server}"
    user = proxy.get("username") or ""
    pwd = proxy.get("password") or ""
    prefix, rest = server.split("://", 1)
    if "@" in rest:
        try:
            from urllib.parse import unquote, urlparse

            parsed = urlparse(server)
            if parsed.hostname:
                scheme = parsed.scheme or prefix or "http"
                netloc = parsed.hostname + (f":{parsed.port}" if parsed.port else "")
                u = unquote(parsed.username or "") or str(user)
                p = unquote(parsed.password or "") or str(pwd)
                if u:
                    return (
                        f"{scheme}://{quote(str(u), safe='')}:"
                        f"{quote(str(p), safe='')}@{netloc}"
                    )
                return f"{scheme}://{netloc}"
        except Exception:
            pass
        return server
    if user:
        return f"{prefix}://{quote(str(user), safe='')}:{quote(str(pwd), safe='')}@{rest}"
    return server


def _build_state_targeted_proxy(
    base: Dict[str, Any],
    state_code: str,
    country: str = "US",
    *,
    state_literal: Optional[str] = None,
    state_variant_index: int = 0,
    city: Optional[str] = None,
) -> Dict[str, Any]:
    """Return a rotating-gateway proxy with state/country targeting and a
    fresh session id in the username (Smartproxy, Bright Data, etc.)."""
    if not base:
        return {}
    _country = (country or "US").strip().upper()
    _norm_state = _normalize_state(state_code) or _normalize_state(state_literal or "")
    try:
        from proxy_provider_module import (  # noqa: WPS433
            _apply_targeting_to_username,
            _detect_profile as _pp_detect_profile,
            _gateway_base_username,
            _rotate_session_in_username,
            _state_targeting_variants as _pp_state_variants,
        )
    except Exception:
        return dict(base)
    # Static proxies — no gateway DSL to rewrite.
    if not base.get("is_rotating_gateway"):
        return dict(base)

    server = base.get("server") or ""
    scheme = "http"
    if server.startswith("https://"):
        scheme = "https"
    elif server.startswith("http://"):
        scheme = "http"

    username = (base.get("username") or "").strip()
    password = base.get("password") or ""
    if not username:
        raw = (base.get("raw") or "").strip()
        if "@" in raw:
            auth = raw.split("@", 1)[0]
            if "://" in auth:
                auth = auth.split("://", 1)[1]
            if ":" in auth:
                username, _, password = auth.partition(":")

    host = _host_from_proxy_server(server)
    username = _gateway_base_username(username, host)
    _profile = _pp_detect_profile(host, "", username)
    _state_for_target = ""
    if _norm_state:
        if state_literal:
            _state_for_target = str(state_literal).strip()
        else:
            _variants = _pp_state_variants(_norm_state, _profile)
            _idx = max(0, int(state_variant_index or 0)) % max(len(_variants), 1)
            _state_for_target = _variants[_idx] if _variants else _norm_state
    _targeting: Dict[str, Any] = {
        "country": _country or "US",
        "_want_sid": True,
        "force_replace": True,
        # Keep probe TCP and Chromium TCP on the same exit IP so the
        # uniqueness check matches the IP Affise actually records.
        "sticky_minutes": 10,
    }
    if _state_for_target:
        _targeting["state"] = _state_for_target
    _city = (city or "").strip()
    if _city:
        _targeting["city"] = _city
    targeted_user = _apply_targeting_to_username(
        username,
        host,
        _targeting,
    )
    targeted_user = _rotate_session_in_username(targeted_user)

    port_part = server.split("@")[-1] if "@" in server else server.split("://", 1)[-1]
    if not port_part and host:
        port_part = f"{host}:80"

    # Keep server host:port ONLY (same as _parse_proxy_line). Credentials
    # live in username/password — embedding them in server breaks
    # _probe_proxy_geo which re-composes the URL and double-embeds auth.
    new_server = f"{scheme}://{port_part}"
    raw_line = (
        f"{scheme}://{targeted_user}:{password}@{port_part}"
        if targeted_user
        else new_server
    )

    out = dict(base)
    out["server"] = new_server
    out["username"] = targeted_user
    out["password"] = password
    out["raw"] = raw_line
    out["is_rotating_gateway"] = True
    return out


def _rotate_gateway_session_proxy(base: Dict[str, Any]) -> Dict[str, Any]:
    """Fresh session id per pick — preserve embedded geo targeting on the line."""
    if not base or not base.get("is_rotating_gateway"):
        return dict(base) if base else {}
    username = (base.get("username") or "").strip()
    if not username:
        raw = (base.get("raw") or "").strip()
        if "@" in raw:
            auth = raw.split("@", 1)[0]
            if "://" in auth:
                auth = auth.split("://", 1)[1]
            if ":" in auth:
                username, _, _pwd = auth.partition(":")
    try:
        from proxy_provider_module import _extract_embedded_gateway_targeting  # noqa: WPS433
        embedded = _extract_embedded_gateway_targeting(username)
    except Exception:
        embedded = {}
    _country = str(embedded.get("country") or "US").strip().upper() or "US"
    _state = ""
    _slug = embedded.get("state_slug") or ""
    if _slug:
        _state = _normalize_state(_slug.replace("_", " ")) or _slug.upper()[:2]
    return _build_state_targeted_proxy(base, _state, _country)


